insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Расскажите, как устроен HashMap изнутри. Что происходит при put, коллизии и расширении?', 'HashMap внутри — массив Node<K,V>[] table, который создаётся лениво при первом put (через resize()); дефолтная ёмкость 16 (DEFAULT_INITIAL_CAPACITY = 1 << 4), load factor 0.75 (DEFAULT_LOAD_FACTOR), порог threshold = capacity * loadFactor. Индекс бакета считается как (n - 1) & hash, поэтому ёмкость всегда степень двойки, а хеш предварительно перемешивается методом hash(): h ^ (h >>> 16), чтобы старшие биты влияли на младшие. Все константы проверяемы в исходнике java.util.HashMap: TREEIFY_THRESHOLD = 8, UNTREEIFY_THRESHOLD = 6, MIN_TREEIFY_CAPACITY = 64, MAXIMUM_CAPACITY = 1 << 30. Коллизии внутри бакета сначала разрешаются связным списком, а при длине >= 8 и ёмкости таблицы >= 64 бакет превращается в красно-чёрное дерево (TreeNode); если ёмкость меньше 64, вместо treeify делается resize — отсюда практический совет сразу задавать new HashMap<>(expectedSize / 0.75f + 1). При расширении ёмкость удваивается, и в Java 8 хеш не пересчитывается: узел остаётся на том же индексе или уезжает на index + oldCap в зависимости от бита (e.hash & oldCap) == 0. null-ключ допускается ровно один (hash(null) = 0, бакет 0), значения null допустимы; итераторы fail-fast по modCount и бросают ConcurrentModificationException. Один конкурентный resize в Java 7 приводил к зацикливанию списка и 100% CPU; в Java 8 цикл убрали, но гонки всё равно теряют данные — нужен ConcurrentHashMap.', 'Почему load factor именно 0.75, а не 0.5 и не 1.0? Что будет, если у всех ключей hashCode() возвращает константу — как деградирует get и сколько займёт памяти на 1 млн элементов? Как сделать LRU на LinkedHashMap с accessOrder = true и removeEldestEntry?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Контракт equals/hashCode: что он требует, что ломается при нарушении и почему ключ в HashMap должен быть immutable?', 'Контракт из javadoc Object: рефлексивность, симметрия, транзитивность, консистентность (при неизменных полях результат стабилен), x.equals(null) == false и, главное, если equals возвращает true, hashCode обязан совпадать; обратное неверно — равные хеши не означают равенство. Компилятор этого не проверяет: переопределили equals — обязаны переопределить hashCode, иначе два логически равных объекта попадут в разные бакеты, и HashMap будет содержать два ключа с одинаковым смыслом. Нарушение симметрии (например, equals сравнивает через instanceof в иерархии и игнорирует подкласс) ломает contains/remove у ArrayList и HashSet; пример с Lombok — @EqualsAndHashCode по умолчанию callSuper = false, и поля родителя не участвуют, что для наследников даёт ложные совпадения. Если объект-ключ изменить после put (изменить поле, участвующее в hashCode), запись станет недостижимой: get вернёт null, а remove не найдёт элемент — классический leak в HashMap/HashSet. Поэтому ключом должен быть immutable-объект: String, Integer, record, enum; альтернатива — хранить идентификатор (id), а не сущность. Для собственной реализации берите Objects.equals и Objects.hash (или ручной расчёт простых чисел) и покрывайте контракт-тестами (EqualsVerifier).', 'Почему в иерархии классов рекомендуют getClass() вместо instanceof в equals — какие трейд-оффы (в частности Hibernate-прокси)? Что произойдёт с HashMap при 1 млн ключей и hashCode(), возвращающим всегда 42? Чем record-ключа отличается от Lombok @Data-ключа по безопасности?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как ConcurrentHashMap обеспечивает потокобезопасность в Java 8+ и почему в нём запрещены null?', 'В Java 8 сегментов больше нет: таблица Node<K,V>[] table (volatile), а запись в пустой бакет делается через CAS (casTabAt), в занятый — под synchronized (f) по головному узлу бакета, то есть блокировка гранулярная на бакет, а не на всю мапу. Размер считается не одним счётчиком, а массивом CounterCell[] (подход Striped64, как в LongAdder), поэтому put не сериализуется на size++; sumCount() даёт согласованное на момент вызова значение без общей блокировки. Расширение выполняет cooperative transfer: потоки, попавшие в бакет с ForwardingNode, помогают переносить таблицу, а не ждут одного потока. Treeify работает как в HashMap: TREEIFY_THRESHOLD = 8 при MIN_TREEIFY_CAPACITY = 64. null-ключи и null-значения запрещены, потому что в конкурентной среде get(key) == null неотличим от «значение равно null», и это делает невозможным атомарный контракт computeIfAbsent; вместо null используется отдельный sentinel-объект или Optional. Атомарные compound-операции: putIfAbsent, computeIfAbsent, compute, merge, replace — их нельзя заменить на if (map.get(k) == null) map.put(k, v) (check-then-act). Важно: код внутри computeIfAbsent выполняется под блокировкой бакета, поэтому в нём нельзя делать долгие вызовы (база, сеть) и рекурсивно обновлять ту же мапу. Итераторы weakly consistent: не бросают ConcurrentModificationException, но не дают снапшота.', 'Чем Collections.synchronizedMap хуже ConcurrentHashMap на 64 потоках? Как посчитать счётчик по ключу атомарно — merge(k, 1, Integer::sum) или compute? Что не так с computeIfAbsent, вызывающим внешний сервис под блокировкой бакета?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'TreeMap и NavigableMap: сложность, методы, чем заменить в конкурентной среде?', 'TreeMap — красно-чёрное дерево, O(log n) на get/put/remove, реализует NavigableMap и SortedMap, ключи сортируются естественным порядком (Comparable) или заданным Comparator; null-ключи запрещены (NPE при сравнении), null-значения допустимы. Из NavigableMap спрашивают floorKey/ceilingKey, lowerKey/higherKey, firstEntry/lastEntry, pollFirstEntry/pollLastEntry, а также subMap/headMap/tailMap — это представления (backed views) на том же дереве: изменения видны в обе стороны, а не копии. Перф: для 1 млн элементов put/get — примерно 20 сравнений, но каждое сравнение — виртуальный вызов compareTo/compare, поэтому TreeMap заметно медленнее HashMap и по памяти дороже (узел хранит цвет и 3 ссылки). TreeMap не потокобезопасен; для конкурентного сортированного доступа берут ConcurrentSkipListMap — skiplist с ожидаемым O(log n), weakly consistent итераторами и без блокировки на чтение; в Java 21 он и TreeMap реализуют SequencedMap. TreeSet устроен аналогично — внутри обёртка над TreeMap с фиктивным значением. Практические советы: Comparator должен быть консистентен с equals (иначе Set/Map ведут себя неинтуитивно), для денежных сумм/таймстемпов не использовать double-ключи, а для «последний по времени» лучше ConcurrentSkipListMap/SkipList, чем Collections.sort на каждой вставке.', 'Как сделать конкурентный LRU-кэш? subMap при мутации исходного дерева — что происходит и как защититься? Что будет, если Comparator нарушает транзитивность?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как построить immutable-класс в Java и чем List.copyOf отличается от Collections.unmodifiableList?', 'Правила: класс final, все поля private final, инициализация только в конструкторе, никаких сеттеров и методов, меняющих состояние; вложенные изменяемые объекты надо копировать (defensive copy) и в конструкторе, и в геттерах. Collections.unmodifiableList(list) — это представление: если кто-то держит ссылку на исходный список, он продолжает его менять и immutable-объект меняется вместе с ним; List.copyOf(list), как и List.of/Map.copyOf (Java 10), делает настоящую копию и отклоняет null-элементы. Плюсы immutable: объект безопасно публикуется между потоками — final-поля дают гарантии видимости по JLS 17.5 (safe publication без синхронизации), пригоден как ключ HashMap/элемент HashSet, кэшируется и шарится без блокировок. Эталоны в JDK: String, Integer, BigDecimal, LocalDate, List.of; с Java 16 record автоматически даёт final-поля и корректные equals/hashCode/toString, но это shallow immutability — список внутри record остаётся изменяемым, если его не скопировать. Kotlin-аналоги: val, data class, но полная неизменяемость достигается только через неизменяемые структуры или копии. Цена: аллокации при каждом изменении и плохая применимость для агрегатов с частой мутацией (там лучше mutable + синхронизация).', 'Как final-поля связаны с JMM и публикацией объекта без synchronized? Что такое benign data race и когда ленивая инициализация в immutable-классе допустима? Как правильно отдать наружу массив из такого класса?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Generics: почему нельзя new T[] и instanceof List<String>? Объясните PECS и wildcards.', 'Generics реализованы через type erasure: параметры типов стираются до границ (Object или первого bound), поэтому List<String> и List<Integer> в байткоде — один класс List, а информация о типе доступна только компилятору. Отсюда запреты: нельзя перегружать методы по параметру типа (m(List<String>) и m(List<Integer>) — clash), нельзя instanceof List<String> (только List<?> или проверка элемента), нельзя new T[]/new List<String>[] — можно Array.newInstance(clazz, n) при наличии Class<T> или непараметризованный массив. Компилятор при необходимости генерирует bridge-методы, а raw-типы (List вместо List<String>) ведут к unchecked-предупреждениям и heap pollution (в списке оказывается не тот тип, ClassCastException позже) — для varargs это решается @SafeVarargs. Wildcards по правилу PECS: List<? extends Number> — producer, читать можно (get возвращает Number), писать нельзя (кроме null), потому что неизвестен точный тип элемента; List<? super Integer> — consumer, write-only: add(Integer) разрешён, get вернёт Object. Инвариантность: List<String> не является List<Object>, поэтому List<Object> принимает Object, а List<?> — только null. Примеры из JDK: Collections.copy(List<? super T> dest, List<? extends T> src), Collections.max(Collection<? extends T>, Comparator<? super T>), Stream.map(Function<? super T, ? extends R>). Wildcard capture требует helper-метода со своим типовым параметром. В Kotlin это решают declaration-site variance (out/in) и use-site-проекции, но erased JVM-ограничения остаются те же.', 'Как обойти erasure при создании типизированного массива и почему это небезопасно? Зачем нужен Comparable<? super T> в Collections.max? Что компилятор делает при (List<String>) rawList и когда падает cast?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Checked vs unchecked исключения. Как работают try-with-resources и suppressed-исключения?', 'Checked (наследники Exception, кроме RuntimeException) обязаны быть объявлены через throws или обработаны; unchecked (RuntimeException) компилятор не заставляет ловить; Error (OutOfMemoryError, StackOverflowError) обычно не ловят, потому что состояние JVM неопределено. try-with-resources (Java 7) требует AutoCloseable (Closeable уточняет Exception, AutoCloseable бросает Exception), ресурсы закрываются в обратном порядке объявления, а компилятор генерирует код с null-проверками — можно использовать переменную, объявленную до try (Java 9). Ключевая деталь: если тело try бросило исключение и close() тоже бросил, основным остаётся исключение из тела, а исключение из close() попадает в suppressed и достаётся через Throwable.getSuppressed(); если тело отработало нормально, исключение close() становится основным. Multi-catch: catch (IOException | SQLException e) — переменная неявно final, типы не могут быть в отношении наследования. finally выполняется до выхода и опасен: бросок или return в finally перекрывает исходное исключение/результат; return внутри try с finally тоже легко испортить. Исключения дороги из-за fillInStackTrace — не стоит использовать их для управления потоком; для бизнес-ошибок в Spring обычно свой RuntimeException и @ControllerAdvice. В лямбдах Stream нельзя бросить checked-исключение — либо оборачивать в unchecked, либо использовать свой функциональный интерфейс с throws.', 'Какие байткоды генерирует try-with-resources (addSuppressed)? Как вы отлаживали баг, где реальная причина была в suppressed-исключении? Почему нельзя ловить Throwable?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'String pool, immutability строки и почему конкатенация в цикле — проблема?', 'Строковые литералы интернируются в String pool, который с Java 7 живёт в heap (раньше в PermGen); внутренняя таблица имеет размер, настраиваемый -XX:StringTableSize — в JDK 21 дефолт 65536 бакетов (в JDK 8 было 60013, JDK-8009928), значение округляется до степени двойки, допустимый диапазон от 128 до 2^24. intern() возвращает канонический экземпляр, new String(...) всегда создаёт новый объект в heap (плюс литерал в пуле), поэтому == сравнивает ссылки и для строк практически всегда нужен equals. String immutable: final-класс, private final byte[] value, копия при усечении; до Java 9 было char[]; в Java 9+ Compact Strings (JEP 254) — byte[] с флагом coder (LATIN1 или UTF16) экономит ~40% памяти на ASCII-тексте. Immutability даёт: безопасную передачу между потоками, кэширование хеша (внутреннее поле hash), пригодность как ключа HashMap, безопасность для class loading и SQL. Конкатенация в цикле через + даёт O(n^2) аллокаций, компилируется в StringBuilder.append (с Java 9 — в invokedynamic со StringConcatFactory, JEP 280), а константные выражения из final static String сворачиваются на этапе компиляции. Дубликаты строк можно чистить -XX:+UseStringDeduplication (работает с G1), substring с Java 7 копирует массив, а не делит его, поэтому утечек через substring больше нет.', 'Почему String сделали immutable — приведите три причины? Как быстро проверить, лежит ли строка в пуле? Как поломали двусторонние API, изменяя String?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Optional: где он уместен, а где вреден? Чем orElse отличается от orElseGet?', 'Optional задуман как тип возвращаемого значения метода, у которого может не быть результата (позиция Брайана Гетца: не для полей и не для параметров), он не Serializable и не поддерживает наследование. orElse(value) вычисляет аргумент всегда, даже если значение есть (опасно, если это вызов БД/репозитория), а orElseGet(Supplier) вызывает лямбду только при пустом Optional; orElseThrow(() -> new NotFoundException()) — предпочтительный способ завершить pipeline. Полезные методы: map/flatMap/filter, ifPresent, ifPresentOrElse (Java 9), stream() (Java 9), isPresent + get — код-смелл, для типового случая есть orElseThrow. Не стоит: держать Optional в коллекциях (Map<String, Optional<T>>), в DTO без Jackson Jdk8Module (падает/сериализуется как объект), в параметрах метода (заставляет всех оборачивать), для примитивов (боксинг — есть OptionalInt/OptionalLong/OptionalDouble, но и они аллоцируют объект). В hot path Optional добавляет аллокацию на каждый вызов и может создавать мусор в молодом поколении — иногда дешевле вернуть null и задокументировать @Nullable или Objects.requireNonNullElse. Kotlin закрывает задачу на уровне типов: T? не требует обёртки-объекта и проверяется компилятором, поэтому в Kotlin-коде Optional не идиоматичен. Отдельно: Optional.orElseThrow без аргумента бросает NoSuchElementException — в API-слое это обычно неправильный ответ клиенту.', 'Когда Optional ухудшает производительность и как это доказать (JMH)? Как Optional ведёт себя в Jackson/Lombok и какие есть обходные пути? Почему Optional в параметре метода — антипаттерн?' from categories where slug = 'java-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Records: что генерируется, что можно и нельзя, как это соотносится с Lombok @Value?', 'record Point(int x, int y) — это final-класс, неявно наследующий java.lang.Record, с private final полями, каноническим конструктором, акцессорами без префикса get (x(), y()), а также сгенерированными equals, hashCode и toString по всем компонентам; JEP 395 — финал в Java 16, в Java 17 вошло в LTS-базлайн. Компактный конструктор record Point { if (x < 0) throw new IllegalArgumentException(); } позволяет валидировать/нормализовать компоненты, присваивать поля в нём напрямую нельзя — компилятор добавит неявные this.x = x; дополнительные конструкторы обязаны делегировать в канонический через this(...). Ограничения: нельзя объявить instance-поля, нельзя наследоваться от класса (только implements интерфейсы), нельзя использовать как JPA @Entity (в Hibernate 6 records годятся для проекций/встраиваемых), нельзя быть abstract. Record — shallow immutable: массив или список внутри остаётся мутабельным, нужен явный List.copyOf. Сериализация record не использует writeObject/readObject, идёт через канонический конструктор, поэтому инварианты не обходятся. С Lombok @Value/@Data сравнение простое: records — языковая фича без плагина-процессора, но нет сеттеров, builder и @Builder/@AllArgsConstructor, поэтому для сущностей всё ещё Lombok, а для DTO/ключей/событий Kafka — record. С Java 21 record patterns дают деструктуризацию: case Point(int x, int y) ->, в том числе вложенную.', 'Что генерирует компактный конструктор и почему нельзя переприсвоить компонент? Как records работают с Jackson и Hibernate (нужен ли -parameters)? Почему record нельзя сделать прокси?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Sealed-классы и pattern matching for switch: как вместе они дают алгебраические типы, и как switch понимает исчерпываемость?', 'sealed interface Shape permits Circle, Square (JEP 409, финал в Java 17) ограничивает иерархию: все прямые наследники обязаны находиться в том же модуле и пакете (или в том же файле), а каждый наследник помечается final, sealed или non-sealed. Компилятор знает полный список вариантов, поэтому switch по sealed-типу может быть исчерпывающим без default, а добавление нового подтипа ломает сборку в местах, где switch не обновлён, — это и есть главный практический выигрыш. Pattern matching for switch (JEP 441) стал финальным в Java 21: case Integer i ->, case Point(int x, int y) -> (record patterns, JEP 440), case null -> отдельной ветвью, guard-условия через when: case Point(int x, int y) when x > 0 ->. Проверки доминирования выполняет компилятор: недостижимая ветка — ошибка компиляции, а null обрабатывается до default, иначе выбрасывается NullPointerException (в отличие от старого switch, который тоже падал). Pattern matching для instanceof (JEP 394, финал в Java 16) даёт if (obj instanceof String s && s.length() > 3) — переменная в области видимости только при истинности условия. В байткоде Java 21 switch по типам компилируется через invokedynamic (SwitchBootstraps.typeSwitch), поэтому JIT оптимизирует его лучше длинных цепочек instanceof. На практике sealed + records + switch — это события Kafka, состояния платежа, Result-типы; сравнение с Scala/Kotlin: в Kotlin sealed-иерархия плюс when проверяется компилятором с 1.6 (предупреждение) и 1.7 (ошибка).', 'Как вы моделировали доменную иерархию до 17 и что дал переход? Чем опасно non-sealed? Что произойдёт с бинарной совместимостью, если в sealed-иерархию добавить новый подтип и пересобрать только часть модулей?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Что нового в языке принесла Java 17 и Java 21? Sequenced Collections, текстовые блоки, и что вы реально применяли после миграции?', 'Java 17 (LTS, сентябрь 2021) закрепила records (финал в 16), sealed-классы (JEP 409), pattern matching для instanceof, switch expressions, текстовые блоки (финал в 15, JEP 378), а также JEP 403 (strong encapsulation — внутренние API JDK закрыты), JEP 411 (SecurityManager объявлен deprecated for removal), JEP 356 (интерфейс RandomGenerator, RandomGeneratorFactory). Текстовые блоки: """ ... """, компилятор сам удаляет инцидентный отступ (по минимальному отступу и позиции закрывающего """), поддерживает escape \s, перенос строки через \ и метод formatted(placeholders) — идеально для SQL, JSON и HTML в тестах. Java 21 (LTS, сентябрь 2023): JEP 444 виртуальные потоки (финал), JEP 431 Sequenced Collections, JEP 440 record patterns, JEP 441 pattern matching for switch, JEP 439 Generational ZGC (-XX:+ZGenerational, дефолтом стал в Java 23 через JEP 474), JEP 453 Structured Concurrency (preview), JEP 445 unnamed classes и instance main (preview), JEP 451 предупреждение о динамической загрузке агентов. Sequenced Collections вводят SequencedCollection, SequencedSet, SequencedMap с методами getFirst/getLast/addFirst/addLast/removeFirst/removeLast/reversed; их реализуют List, Deque, LinkedHashSet/LinkedHashMap, а также SortedSet/SortedMap (TreeMap). В SequencedMap добавлены putFirst/putLast, firstEntry/lastEntry, pollFirstEntry/pollLastEntry; вызов reversed() возвращает представление, изменения отражаются в исходной коллекции. Практический эффект: получение первого/последнего элемента LinkedHashMap больше не требует итератора и обхода — до 21 это был O(n). При миграции 17 -> 21 в первую очередь стоит перевести блокирующий IO на виртуальные потоки (spring.threads.virtual.enabled=true) и один-два горячих сервиса на ZGC.', 'Что из Java 21 вы включали в проде и почему? Какие фичи ещё в preview и почему вы их не берёте? Как проходила миграция 13 -> 17 -> 21 в вашей команде — какие были блокеры?' from categories where slug = 'java-17-21';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Из чего состоит память JVM? Где живёт метаспейс и как считать лимит контейнера?', 'Heap делится на Young (Eden + два Survivor, S0/S1) и Old/Tenured; объекты рождаются в Eden под TLAB (-XX:+UseTLAB), выжившие копируются в Survivor (minor GC), затем продвигаются в Old (major/full). Metaspace — это native-память (не heap!), он заменил PermGen в Java 8 и хранит метаданные классов, методы, константы; по умолчанию размер не ограничен, -XX:MetaspaceSize=21MB задаёт начальный порог, при котором запускается сборка метаспейса, а -XX:MaxMetaspaceSize нужен обязательно в контейнерах, иначе ClassLoader-утечка съест всю память. Code Cache (~-XX:ReservedCodeCacheSize=240MB) держит скомпилированный C1/C2-код, сегментируется (-XX:+SegmentedCodeCache), при переполнении JIT останавливается и производительность падает. Стек потока задаётся -Xss (обычно 1MB на x64 Linux), поэтому 1000 потоков — это порядка 1GB стека. Direct Memory от ByteBuffer.allocateDirect по умолчанию лимитирована -Xmx (-XX:MaxDirectMemorySize) и учитывается как native. Классическая ошибка в Kubernetes: контейнер 512Mi, -Xmx512m — процесс убивается OOMKilled, потому что heap + metaspace + код + стеки + native превышают лимит; правильно -XX:MaxRAMPercentage=70 (Java 10+ видит cgroup-лимиты) и явный -XX:MaxMetaspaceSize. GC roots: стековые фреймы активных потоков, статические поля классов, JNI-ссылки, мониторы и JVM-внутренние структуры.', 'Сколько памяти нужно на 2000 потоков с дефолтным -Xss? Почему Metaspace не в heap? Что покажет VM.native_memory (нужен -XX:NativeMemoryTracking=summary)?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Serial, Parallel, G1, ZGC, Shenandoah — как выбрать сборщик и какими флагами?', 'Serial (-XX:+UseSerialGC) — один поток, stop-the-world, годится для мелких heap (до ~100-200MB), CLI и batch-скриптов; минимум накладных расходов. Parallel (-XX:+UseParallelGC) — многопоточный STW, ориентирован на throughput, был дефолтом в Java 8; подходит для batch/ETL, где важна пропускная способность, а не паузы. G1 (-XX:+UseG1GC, дефолт с Java 9, JEP 248) — региональный, concurrent marking, цель по паузе -XX:MaxGCPauseMillis=200 (дефолт), хорошо работает на heap от ~2-4GB до десятков GB; типичный выбор для микросервисов на 2-8GB. ZGC (-XX:+UseZGC) — concurrent, паузы менее 1 мс независимо от размера heap (до 16TB по спецификации), использует colored pointers и load barriers; в Java 21 поколенческий режим включается отдельно -XX:+ZGenerational, дефолтным он стал только в Java 23 (JEP 474). Shenandoah (-XX:+UseShenandoahGC) — низкие паузы, доступен в большинстве OpenJDK-сборок (в некоторых был вырезан). Epsilon (-XX:+UseEpsilonGC) — не собирает мусор, нужен только для тестов пропускной способности и оценки аллокаций. CSP: Serial/Parallel — throughput, G1/ZGC/Shenandoah — latency. Практика: для сервиса с SLA p99 < 20мс и heap 8-32GB — G1 с -XX:MaxGCPauseMillis=100 или ZGC; для аналитического batch на 64GB — Parallel. CMS удалён в Java 14 (JEP 363), поэтому в 17/21 его нет. Проверять выбор нужно по GC-логам и метрикам, а не по интуиции.', 'Как по GC-логам понять, что сборщик не справляется? Какой GC для heap 90GB и p99 < 10 мс — и почему не Parallel? Что такое throughput vs latency vs footprint?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'G1: как он устроен, что такое humongous-объекты и как вы тюните heap?', 'G1 делит heap на примерно 2048 регионов размером 1-32MB (-XX:G1HeapRegionSize, дефолт вычисляется из -Xmx), каждый регион в момент времени играет роль Eden, Survivor, Old или Humongous. Concurrent marking стартует при достижении порога -XX:InitiatingHeapOccupancyPercent=45 (IHOP) от всего heap, после чего идут смешанные сборки (young + часть old-регионов с наибольшим объёмом мусора). Объект размером >= 50% региона считается humongous, размещается в непрерывных регионах и часто становится причиной фрагментации и Full GC — поэтому не стоит держать гигантские массивы/строки; помогает увеличение G1HeapRegionSize. Диагностика: -Xlog:gc*,gc+heap=info:file=/var/log/app/gc.log:time,uptime,level,tags:filecount=5,filesize=20M, а также JFR и Graphana/JMX (метрики GarbageCollectorMXBean). Тюнинг: -Xms = -Xmx (убирает ресайз heap и паузы на расширение), -XX:MaxRAMPercentage=70 в контейнерах, -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/dumps, -XX:+ExitOnOutOfMemoryError (чтобы Kubernetes перезапустил под), явный -XX:MaxMetaspaceSize, -XX:+UseStringDeduplication для строковых дубликатов. Не ставьте MaxGCPauseMillis заведомо недостижимым (например, 5 мс): G1 будет делать много коротких young GC, суммарный throughput упадёт. Если после Full GC занятость Old близка к 100% и растёт — это не тюнинг, а утечка, смотрите heap dump.', 'Как по gc.log отличить утечку от большого рабочего набора? Почему -Xms != -Xmx может быть вреден для latency? Как вы считали эффективность GC-тюнинга — какие метрики сравнивали?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как искать утечки памяти в проде? Какие утечки Java-разработчик создаёт чаще всего?', 'Признаки: после Full GC потребление Old/whole heap не возвращается к базовой отметке и ступенями растёт, растут GC-паузы и latency, появляются OutOfMemoryError с разными сообщениями — Java heap space, GC overhead limit exceeded, Metaspace, Direct buffer memory, unable to create native thread (последние два — про native-память и лимиты, а не про heap). Типовые причины: статические коллекции и кэши без eviction (забыли maximumSize у Caffeine/Guava, либо кэш ключуется неограниченным набором), слушатели/подписки без отписки (Kafka consumer, EventBus, Spring-контексты), ThreadLocal в пулах потоков (значение живёт пока жив поток, нужен remove() в finally), ClassLoader-утечки при передеплое (статическая ссылка на класс, ThreadLocal, JDBC-драйвер), ключи в HashMap с нарушенным equals/hashCode, DirectByteBuffer-утечки (очистка через Cleaner), большие буферы в ThreadLocal, а также незакрытые потоки/каналы. Инструменты: heap dump по -XX:+HeapDumpOnOutOfMemoryError, вручную jcmd <pid> GC.heap_dump /dumps/app.hprof или jmap -dump:live,1; анализ в Eclipse MAT через dominator tree, leak suspects и Path to GC Roots (исключая слабые ссылки), плюс сравнение двух дампов по histogram. Для аллокационного профиля без дампа — JFR (jdk.ObjectAllocationSample) или async-profiler -e alloc с флеймграфом; по времени жизни объектов ориентируются на class histogram (jcmd <pid> GC.class_histogram). В проде важно отличать реальную утечку от высокого давления (много недостижимого мусора) и не тащить дамп в прод-контейнер — снимают один инстанс и анализируют офлайн.', 'Расскажите про конкретную утечку, которую нашли, — как обнаружили и починили? Как искать утечку, если heap dump снять нельзя (только метрики Prometheus)? Почему ThreadLocal в пуле потоков — классическая утечка?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'JFR и профайлинг: как профилировать прод-сервис с минимальными накладными расходами?', 'JFR встроен в JDK (с Java 11 полностью в OpenJDK), включается флагом -XX:StartFlightRecording=duration=60s,filename=/tmp/app.jfr,settings=profile или на лету через jcmd <pid> JFR.start/JFR.dump; накладные расходы обычно 1-2%, что позволяет снимать записи в проде. Полезные события: jdk.ExecutionSample (стеки потоков для CPU), jdk.ObjectAllocationSample (аллокации, Java 16+), jdk.GCPhasePause, jdk.ThreadPark, jdk.JavaMonitorEnter (контеншен мониторов, находится в jdk.JavaMonitorEnter/EnterTime), jdk.SocketRead/SocketWrite, jdk.FileWrite, а для виртуальных потоков — jdk.VirtualThreadPinned, jdk.VirtualThreadStart. Анализ — в JDK Mission Control (JMC). Для CPU-профиля часто лучше async-profiler: он сэмплирует по perf_events (не только safepoint-семплы), строит флеймграфы, умеет режимы -e cpu, -e alloc, -e lock, -e wall, что позволяет найти не только CPU, но и «кто держит лок» или «кто блокируется на IO». jcmd — швейцарский нож: Thread.print, GC.heap_info, GC.class_histogram, VM.flags, VM.native_memory (нужен -XX:NativeMemoryTracking=summary), JFR.start, JVMTI.agent_load. Для микробенчмарков обязателен JMH (warmup, forks, Blackhole, -prof gc), иначе результаты недостоверны; для нагрузочного теста — Gatling/JMeter с коррелирующими метриками Grafana/Prometheus (latency p50/p95/p99, RPS, GC, thread pool queue, connection pool).', 'Чем async-profiler лучше встроенного сэмплера и почему safepoint bias важен? Как вы искали lock contention в живой системе? Какие события JFR вы бы добавили в постоянный мониторинг?' from categories where slug = 'jvm';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Модель памяти Java и happens-before: почему без синхронизации поток может никогда не увидеть изменение?', 'JMM (JLS 17.4) определяет, какие записи в память видны другим потокам; без синхронизации это data race — JIT и CPU могут переупорядочивать инструкции, значения кэшируются в регистрах и кэшах ядер, поэтому нет ни видимости, ни порядка. Happens-before — отношение гарантированной видимости; ключевые правила (JLS 17.4.5): program order внутри потока, monitor rule (unlock монитора happens-before последующего lock того же монитора), volatile (запись happens-before последующего чтения той же переменной), Thread.start (действия в стартующем потоке видны новому), Thread.join (всё в потоке видно тому, кто вызвал join), interrupt, правило final-полей (JLS 17.5) и транзитивность. Практическое следствие: while (!stop) {} с обычным boolean может крутиться вечно, потому что JIT вынесет чтение из цикла (hoisting) или другой поток никогда не сбросит кэш; с volatile цикл завершается. Без HB другой поток может увидеть частично сконструированный объект — ссылка опубликована, а поля ещё дефолтные (в том числе null вместо значения), поэтому публикация через статическое поле без синхронизации опасна. Safe publication достигается через final-поля в конструкторе, инициализацию в статическом инициализаторе (class init), volatile/AtomicReference, синхронизированный блок или concurrent-коллекцию. На уровне процессора volatile/synchronized превращаются в memory barriers (на x86 запись в volatile — это StoreLoad через locked-инструкцию и mfence).', 'Почему double-checked locking без volatile ломается и как выглядит корректная версия? Что такое benign race и когда он безопасен? Как HB-правило для final связано с гарантией полной инициализации?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'volatile vs synchronized: что именно гарантирует каждый и когда что выбирать?', 'volatile даёт видимость и запрет переупорядочивания (запись happens-before последующего чтения), но не атомарность составных операций: counter++ — это read-modify-write, при 10 потоках потеряются обновления; volatile уместен для флага остановки, для одноразовой публикации ссылки (publication идиома с локальной переменной), для state-машины одного поля. synchronized даёт взаимное исключение плюс видимость и реентрантность: монитор объекта, счётчик удержаний в заголовке объекта; блокировка — на конкретном экземпляре или на Class, поэтому synchronized(this) и synchronized на другом объекте конфликтуют или не конфликтуют по-разному — частая ошибка при использовании разных мониторов. С Java 6 встроены адаптивный спин и оптимизации (lock elision для локальных объектов в JIT, lock coarsening), biased locking удалён в Java 15 (JEP 374) из-за сложности и проблем с виртуальными потоками — на современных JVM разница в стоимости на низком контеншене невелика. Для счётчиков правильный ответ — AtomicInteger/LongAdder, а не volatile и не synchronized на get/set. Ещё нюанс: volatile ссылка не делает потокобезопасным объект, на который она указывает — если внутри mutable-структура, нужны separate-гарантии. В контексте виртуальных потоков (Java 21) synchronized-блок дополнительно пиннит carrier-поток, поэтому там предпочитают ReentrantLock.', 'Как на x86 реализуется запись в volatile и чтение? Почему убрали biased locking? Что произойдёт, если синхронизировать на строковом литерале или на Integer из кэша?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'ReentrantLock, ReadWriteLock и StampedLock: что дают сверх synchronized и где ломаются?', 'ReentrantLock (java.util.concurrent.locks) даёт: tryLock() и tryLock(timeout, unit) без блокировки, lockInterruptibly() (прерываемое ожидание), справедливый режим new ReentrantLock(true) — честная очередь, снижает пропускную способность, но борется со starvation, и объекты Condition: несколько независимых wait-set на одном lock (в отличие от одного wait/notify у монитора), с await/signal/awaitNanos. Обязательный паттерн — lock() и unlock() в finally; забытый unlock оставляет монитор навсегда. Через ReentrantLock легко реализовать таймауты и избежать дедлока: не получил второй лок за N мс — отпусти первый и повтори (противоположность классическому lock ordering). ReentrantReadWriteLock: читатели параллельно, писатель один; поддерживает downgrade (взять write, затем read, затем отпустить write), upgrade не поддерживается (дедлок), при частом чтении возможен starvation писателей, но режим fair его лечит. StampedLock (Java 8): оптимистичное чтение tryOptimisticRead() + validate(stamp) без блокировки в надежде, что писателя не было — быстрее в read-heavy сценариях, но не реентрантен, не поддерживает Condition и не имеет владельца; инвалидируется при любом write. Все три, в отличие от synchronized, не пиннят виртуальные потоки, что важно в Java 21. Дополнительно: LockSupport.park/unpark, Semaphore для лимита параллелизма, CountDownLatch/CyclicBarrier/Phaser для координации — но в прикладном коде чаще закрывают через concurrent collections и CompletableFuture.', 'Как вы предотвращаете дедлоки в сервисе (lock ordering, timeouts, tryLock)? Что такое optimistic read в StampedLock и как валидируется? Почему fair lock дороже?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Атомики: как работает CAS, что такое ABA и почему AtomicLong под контеншеном проигрывает LongAdder?', 'AtomicInteger/AtomicLong/AtomicReference построены на CAS (compareAndSet): JVM вызывает нативный примитив (VarHandle.compareAndSet, ранее Unsafe), который на x86 компилируется в lock cmpxchg — атомарная read-modify-write операция процессора, на ARM — LL/SC-подобные инструкции; при неуспехе цикл повторяется (spin), поэтому под высоким контеншеном потоки жгут CPU. Атомики дают семантику volatile (видимость) плюс атомарность; важно: getAndIncrement возвращает предыдущее значение, а если нужен результат — incrementAndGet, для коллекций — AtomicReference. ABA-проблема: поток прочитал A, другой сменил на B и обратно на A, CAS считает, что ничего не изменилось, хотя состояние «прошло цикл»; лечится AtomicStampedReference (версия) или AtomicMarkableReference, либо структурно (не удалять/возвращать узлы). LongAdder/LongAccumulator (Java 8) держат массив ячеек (Striped64) и при контеншене разные потоки инкрементируют разные ячейки, поэтому масштабируется лучше — на 8-16 потоках ускорение часто в 2-4 раза; цена — sum() не является атомарным снапшотом и может пропустить конкурентное обновление, а памяти больше. Для метрик и счётчиков статистики в проде берут LongAdder/DoubleAdder, для счётчика с точным мгновенным значением и логикой на нём — AtomicLong. Copy-on-write: CopyOnWriteArrayList на чтение без блокировок, запись копирует массив — хорош для редко меняющийся конфигурации, плох для частых вставок. Для изменения поля существующего объекта без обёртки — AtomicIntegerFieldUpdater. С Java 9 вместо Unsafe используют VarHandle с режимами getAcquire/setRelease/compareAndExchange, что позволяет строить более дешёвые схемы (release/acquire вместо полного fence).', 'Как бы вы реализовали lock-free очередь и какие проблемы там ловят (hazard pointers)? Почему false sharing портит производительность LongAdder и что такое @Contended? Когда volatile-счётчик допустим?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'ThreadPoolExecutor: объясните порядок обработки задач и как подобрать параметры пула?', 'Конструктор принимает corePoolSize, maximumPoolSize, keepAliveTime, TimeUnit, workQueue, threadFactory и RejectedExecutionHandler. Алгоритм исполнения: если потоков меньше core — создаётся новый поток; иначе задача кладётся в очередь; если очередь заполнена и потоков меньше maximum — создаётся ещё поток; если и это невозможно — вызывается rejection-политика. Критично: с неограниченной LinkedBlockingQueue maximumPoolSize не играет роли — задачи копятся, растёт latency и в итоге OutOfMemoryError; поэтому для ограниченного пула берут ArrayBlockingQueue с очередью порядка 2-10x от пула. Политики: AbortPolicy (дефолт, бросает RejectedExecutionException — сигнал, что система перегружена), CallerRunsPolicy (backpressure: задача выполняется потоком-отправителем, входящий трафик тормозится), DiscardPolicy и DiscardOldestPolicy (для метрик/телеметрии, где потеря допустима). Полезно: allowCoreThreadTimeOut(true), prestartAllCoreThreads(), свой ThreadFactory с осмысленными именами (диагностика через Thread.print), и мониторинг getActiveCount()/getQueue().size()/getCompletedTaskCount() в Grafana. Размер: CPU-bound примерно N+1, IO-bound по формуле N * (1 + W/C), где W — время ожидания, C — время вычислений (Brian Goetz, Java Concurrency in Practice); например, при W/C = 4 и 8 ядрах получается ~40 потоков. Добавлять потоки бессмысленно, если узкое место — БД или внешний сервис: там ограничивают пул соединений. Типовые ошибки фабрик Executors: newFixedThreadPool и newSingleThreadExecutor используют неограниченную очередь, newCachedThreadPool — SynchronousQueue с maximumPoolSize = Integer.MAX_VALUE (лавина потоков, OOM native thread), а newScheduledThreadPool держит задачи в DelayedWorkQueue; в продакшене пул конфигурируют явно.', 'Как вы определяли размер пулов для сервиса и как проверяли, что не ошиблись? Что делать при RejectedExecutionException в проде? Меняет ли что-то переход на виртуальные потоки для IO-bound задач?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'CompletableFuture: чем thenApply отличается от thenCompose и как не убить общий пул?', 'CompletableFuture (Java 8) — асинхронные цепочки и комбинации: supplyAsync/runAsync запускают задачу, thenApply преобразует результат, thenCompose «уплощает» вложенный CompletableFuture (аналог flatMap), thenCombine объединяет два независимых результата, thenAccept/runAfterBoth — терминальные, allOf/anyOf — ожидание группы (allOf возвращает CompletableFuture<Void>, результаты надо собирать в Stream.map(CompletableFuture::join)). Разница суффикса Async принципиальна: thenApply выполнится в потоке, который завершил предыдущий этап (может быть поток пула Tomcat или main), а thenApplyAsync — в commonPool или в переданном Executor; для контроля блокирующих шагов всегда передавайте свой executor. Обработка ошибок: exceptionally (восстановление), whenComplete (side effect, не меняет результат), handle (преобразует и результат, и исключение); исключение внутри цепочки оборачивается в CompletionException. Таймауты: orTimeout и completeOnTimeout (Java 9), delayedExecutor для отложенного запуска; без таймаута цепочка может ждать вечно, поэтому в прод-коде таймаут обязателен. По умолчанию асинхронные этапы идут в ForkJoinPool.commonPool() с параллелизмом = availableProcessors - 1, который общий для всего JVM: блокирующий вызов там останавливает и параллельные стримы, и другие цепочки — либо используйте свой пул, либо (в Java 21) виртуальные потоки Executors.newVirtualThreadPerTaskExecutor(). Ещё ловушки: не вызывайте get() без таймаута в потоке сервера, allOf не ждёт завершения при исключении в одном из элементов, а забытый join оставляет работу без обработки ошибок.', 'Как вы связываете CompletableFuture с контекстом (MDC/traceId) между этапами? Чем allOf + join хуже StructuredTaskScope? Как тестировать асинхронный код без flaky-тестов?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'ForkJoinPool и work-stealing: как устроен и почему parallelStream в проде может навредить?', 'ForkJoinPool — пул с work-stealing: каждый воркер имеет свою двустороннюю очередь, свои задачи берёт с головы (LIFO, свежие данные горячие в кэше), а «украденные» другим воркером — с хвоста (FIFO, крупные куски). Задачи описывают через RecursiveTask/RecursiveAction с fork()/join(), разбивая работу до порога (parallelism = availableProcessors - 1 у commonPool, свой пул создаётся new ForkJoinPool(n), настраивается -Djava.util.concurrent.ForkJoinPool.common.parallelism). Общий пул разделяется всем JVM: parallelStream(), CompletableFuture без executor и параллельные задачи библиотек конкурируют за одни и те же потоки, поэтому блокирующий вызов (HTTP, JDBC) внутри parallelStream останавливает не только своё вычисление, но и чужое. Для блокирующих задач предусмотрен ManagedBlocker (пул при нехватке воркеров создаёт компенсирующие потоки), но в прикладном коде проще передать собственный Executor или использовать виртуальные потоки. Work-stealing не даёт гарантий справедливости и порядка: результат reduce должен быть ассоциативным, иначе ответ зависит от разбиения. Признак неудачного применениия: коллекция маленькая (накладные расходы fork/join больше выигрыша), элемент LinkedList или Stream.iterate (плохой Spliterator, нет эффективного split), внутри stateful-лямбда с общим изменяемым состоянием (гонка, silently wrong results). В Java 21 виртуальные потоки используют собственный планировщик — ForkJoinPool с parallelism = число ядер, maxPoolSize = max(parallelism, 256), FIFO-режимом и параметрами jdk.virtualThreadScheduler.parallelism / maxPoolSize / minRunnable.', 'Как изолировать parallelStream от commonPool в Spring-приложении? Что такое ManagedBlocker и когда он нужен? Как вы доказывали, что параллельный стрим даёт выигрыш (JMH, размер данных)?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Виртуальные потоки в Java 21: как работают, что такое pinning и когда они не помогут?', 'Виртуальные потоки (JEP 444, финал в Java 21) — легковесные потоки, реализованные в JDK, а не в ОС: стек разбит на чанки в heap, монтируется на carrier-поток (ForkJoinWorkerThread планировщика) и размонтируется при блокирующих операциях; создание занимает микросекунды, поэтому можно держать миллионы потоков. API: Thread.ofVirtual().name("req-1").start(task), Thread.startVirtualThread, Executors.newVirtualThreadPerTaskExecutor() (в Spring Boot 3.2 включается spring.threads.virtual.enabled=true). Виртуальные потоки не пулят — они дешёвы, пул только мешает; ThreadLocal работает, но злоупотребление ими съедает heap (у каждого потока свои значения), лучше ScopedValue. Pinning — ситуация, когда виртуальный поток не может размонтироваться и блокирует carrier: это synchronized-блок/метод (до Java 24, где JEP 491 убрал эту проблему) и нативные/foreign-фреймы (JNI, вызовы native-библиотек), а также Object.wait(). Диагностика pinning — JFR-события jdk.VirtualThreadPinned и jdk.VirtualThreadStart, дампы jcmd <pid> Thread.dump_to_file -format=json. Когда не помогут: CPU-bound задачи (ядер не становится больше, parallelism планировщика = количеству ядер), блокировки под synchronized/native в библиотеках (JDBC-драйверы до определённых версий, пулы соединений), лимиты внешней системы (БД выдержит столько же соединений — нужен семафор или ограниченный пул), а также при большом количестве ThreadLocal/больших стеках, которые уезжают в heap. Виртуальные потоки делают блокирующий код масштабируемым, но не заменяют реактивный стек в задачах, где нужны backpressure и композиция потоков событий — там уместнее Flow/Kotlin-корутины.', 'Как вы мигрировали сервис на виртуальные потоки и что изменилось в метриках? Что делать, если внутри библиотеки лежит JNI внутри synchronized? Чем виртуальные потоки отличаются от реактивного WebFlux по модели исполнения?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Structured Concurrency (preview): чем StructuredTaskScope лучше ExecutorService с invokeAll?', 'StructuredTaskScope (java.util.concurrent, JEP 453 — preview в Java 21, требует --enable-preview) задаёт область выполнения: задача разбивается на подзадачи, scope.fork(Callable) возвращает Subtask<T> (в Java 21 это замена Future из предыдущих превью), scope.join() или joinUntil(Instant deadline) ждёт завершения, после чего результат берётся через Subtask.get(). Две готовые политики: ShutdownOnFailure отменяет остальные подзадачи при первой ошибке и даёт throwIfFailed() (аналог гонки с fail-fast), ShutdownOnSuccess возвращает первый успешно завершившийся результат через result() — это паттерн «спроси три реплики/кэш и БД, возьми первый ответ». Главное отличие от ExecutorService: при выходе из блока scope закрывается, все подзадачи гарантированно завершены или отменены — утечки потоков и «забытый shutdown()» становятся невозможны, а структура кода совпадает со структурой задачи (как coroutineScope/supervisorScope в Kotlin или errgroup в Go). Отмена выполняется через Thread.interrupt, поэтому подзадача должна уважать прерывание; наблюдать за жизненным циклом удобно JFR-событиями. Дополнительно scope ограничивает наследование контекста и даёт чёткий скоуп для трассировки/логирования, что важно для MDC. Ограничения: API всё ещё preview, политики нельзя комбинировать произвольно без своего Joiner, а сам scope предполагает дешёвые потоки (виртуальные), иначе сотни подзадач съедят carrier-потоки.', 'Как вы бы моделировали таймаут всей операции и частичный успех? Чем это отличается от CompletableFuture.allOf по обработке ошибок? Как передать traceId в подзадачи?' from categories where slug = 'concurrency';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Ленивость Stream API: что и когда вычисляется? Что такое stateful и short-circuiting операции?', 'Промежуточные операции (map, filter, flatMap, peek, sorted, distinct) ленивы: они только строят pipeline из Sink-ов и не выполняются, пока не вызвана терминальная операция (collect, forEach, reduce, count, findFirst, anyMatch); без терминальной операции не выполнится ни одна строка лямбды. Поэтому peek не годится для обязательных side-эффектов — при отсутствии терминальной операции он не сработает, а при коротком замыкании сработает не для всех элементов. Short-circuiting (limit, findFirst, anyMatch/allMatch/noneMatch, takeWhile/dropWhile из Java 9) позволяют работать с бесконечными стримами Stream.iterate/generate; в Java 9+ у iterate появилась три-аргументная форма iterate(seed, hasNext, next). Stateful-операции (sorted, distinct, limit/skip) буферизуют элементы или требуют всего потока до продолжения, поэтому ломают ленивость и в параллельном режиме дороже: distinct держит HashSet, sorted собирает всё в массив. Стрим одноразовый — повторное использование бросает IllegalStateException (stream has already been operated upon or closed), а закрытие — только для ресурсных стримов (Files.lines, try-with-resources). Полезные мелочи: Stream.ofNullable (Java 9) чистит null, mapToInt/mapToLong избегают боксинга, Stream.toList() (Java 16) даёт неизменяемый список в отличие от collect(Collectors.toList()), IntStream.range/boxed для индексов. Операции можно компоновать в любом порядке, но фильтрация до маппинга обычно дешевле; закон Мура (элементов на операцию) работает на пользу длинным цепочкам только если она без stateful-шагов.', 'Почему peek иногда ничего не печатает? Как понять, что стрим уже потреблён, и как отлаживать pipeline? Что даёт unordered() в параллельном стриме?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Collectors: как работает collect изнутри, какие подводные камни у toMap и groupingBy?', 'Трёхаргументный collect(supplier, accumulator, combiner) показывает суть: supplier создаёт контейнер, accumulator добавляет элемент, combiner сливает два контейнера при параллельной обработке — именно поэтому для параллельных стримов коллектор обязан быть корректным и ассоциативным. Collectors.toMap бросает IllegalStateException при дублирующемся ключе (нужно передать merge-функцию (a, b) -> b) и NPE при null-значении, потому что внутри используется Map.merge; для null-значений приходится писать свой коллектор или фильтровать заранее. groupingBy по умолчанию возвращает HashMap, а порядок теряется — для порядка передайте LinkedHashMap::new, для сортировки TreeMap::new через трёхаргументную перегрузку groupingBy(classifier, mapFactory, downstream); partitioningBy всегда даёт ровно два ключа Boolean. Полезные downstream-коллекторы: counting, summingInt/summingLong, averagingInt, mapping, filtering, flatMapping (Java 9), reducing, maxBy, teeing (Java 12) — два коллектора в один результат (например, среднее + количество за один проход), collectingAndThen для финального преобразования, joining(delimiter, prefix, suffix). toUnmodifiableList/Set/Map (Java 10) сразу отдают неизменяемые коллекции, в отличие от Collections.unmodifiableList. Свой коллектор описывают через Collector.of с characteristics (IDENTITY_FINISH, CONCURRENT, UNORDERED); CONCURRENT позволяет мутировать один общий контейнер без combiner, но только для непараллельных/безопасных случаев. Производительность: цепочки collect с boxing дорогие, для агрегаций по числам лучше mapToInt(...).sum() или цикл; groupingBy с большими кардинальностями аллоцирует много объектов.', 'Как вы собирали Map, где ключ может дублироваться, но нужно накапливать список? Что делает characteristics CONCURRENT и когда он опасен? Как замерить, что стрим быстрее цикла (JMH)?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Параллельные стримы: когда реально ускоряют и как их не сломать?', 'parallelStream()/parallel() используют ForkJoinPool.commonPool() с параллелизмом = availableProcessors - 1 (общий на всю JVM), данные разбиваются Spliterator-ом на чанки, а рекурсивные задачи воруют работу друг у друга. Ускорение реально, когда данных много (обычно от десятков/сотен тысяч элементов), операции независимы и CPU-bound, а структура данных хорошо делится: ArrayList, массивы, IntStream.range — да; LinkedList и Stream.iterate — нет, потому что split даёт половину без первого элемента и распараллеливание фиктивно. Когда вредит: маленький объём (накладные расходы fork/join больше выигрыша), блокирующие вызовы внутри (JDBC/HTTP занимают общие потоки и тормозят весь JVM, включая другие parallelStream и CompletableFuture без executor), stateful-операции — sorted, distinct, limit в параллельном режиме требуют барьеров, а reduce должен быть ассоциативным и без побочных эффектов (иначе результат зависит от разбиения и возникает race). forEachOrdered сохраняет порядок и убивает параллелизм, поэтому для результатов без порядка пишут forEach/unordered(); findFirst дороже findAny. Ещё ловушка: общий изменяемый контейнер в лямбде (list::add) — небезопасно, даже синхронизированная коллекция не гарантирует корректный порядок; используйте collect с корректным коллектором. Изоляция: submit работы в собственный new ForkJoinPool(n), а не в commonPool, — иначе один тяжёлый стрим ломает latency всего сервиса; в контейнере с 2 CPU параллелизм почти всегда проигрывает. Всё измеряют JMH: без warmup и без -prof gc выводы «быстрее/медленнее» недостоверны.', 'Как вы бенчмаркали параллельный стрим и какие цифры получили? Почему commonPool — плохое место для блокирующего IO? Как в Kotlin/корутинах решается та же задача иначе?' from categories where slug = 'stream-api';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Null-safety в Kotlin: ?., elvis, !!, platform types — как избежать NPE и где он всё равно прилетит?', 'Типы T и T? различаются на уровне системы типов: присвоить nullable в non-null нельзя, компилятор заставляет обработать; ?. — безопасный вызов (возвращает null при нулевом receiver), ?: — элвис, возвращающий правое значение (может быть throw/return), !!. — оператор, который бросит NPE с указанием выражения (в проде почти всегда заменяют на requireNotNull/checkNotNull с осмысленным сообщением или на ?: error(...)). Полезно: as? для безопасного каста, let/also/run для работы с non-null (user?.let { send(it) }), filterNotNull, takeIf. Smart casts работают после проверок (if (x != null), is-проверок, Elvis с return), но не для var-полей класса, которые могут измениться другим потоком, и не для свойств из другого модуля (там нужна локальная val-копия или also/let). Ломается null-safety на границе с Java: платформенный тип String! означает, что компилятор не проверяет null вообще, и NPE прилетает в рантайме — поэтому все обращения к Java-API нужно либо явно аннотировать (@Nullable/@NotNull из JSR-305/JetBrains), либо проверять через ?. Остальные источники NPE: reflection и сериализаторы (Jackson/Gson могут выставить null в non-null свойство через Unsafe), неинициализированные lateinit (UninitializedPropertyAccessException при обращении до инициализации), !! и явные requireNotNull/checkNotNull. Kotlin не делает NPE невозможным — он делает его редким и явным; на границе с Java полезно ставить аннотации и покрывать интеграционные тесты с null-значениями от внешних систем.', 'Что такое platform type и как вы чистите границы с Java? Почему lateinit-свойство — риск и когда он оправдан? Как ведёт себя if (obj is String) на платформенном типе?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'data class, sealed-иерархии, object и companion: как в Kotlin моделируют домен?', 'data class генерирует equals, hashCode, toString, copy и componentN по свойствам первичного конструктора; свойства, объявленные вне него, в equals не участвуют (частая ошибка), нельзя быть abstract/sealed/inner, нужен хотя бы один параметр, и copy — shallow (вложенный список копируется по ссылке). Наследоваться от data class нельзя, что логично: полиморфный equals сломал бы контракт. sealed class/interface дают исчерпывающий when: все наследники обязаны находиться в том же модуле и пакете (в Kotlin 1.5+; до этого — в одном файле), а «when» без else для sealed/enum/Boolean обязателен — предупреждение с 1.6, ошибка с 1.7. Это прямой аналог Java sealed (JEP 409) плюс pattern matching, но в Kotlin конструкция работает и для декомпозиции данных: sealed interface Result с data class Ok(val value: T) и data class Failure(val throwable: Throwable). object — синглтон: создаётся лениво при первом обращении, поддерживает интерфейсы, может содержать состояние; им не стоит злоупотреблять как глобальным состоянием. companion object — «статические» члены и фабрики; чтобы они стали настоящим static в байткоде, нужен @JvmStatic, для полей — @JvmField, для констант времени компиляции — const val (только примитивы и String). Для type-safe обёрток над примитивами применяют @JvmInline value class (без аллокации в большинстве случаев, например value class Money(val cents: Long)). В сравнении с enum sealed гибче: варианты могут иметь разный набор полей и свою иерархию.', 'Почему у data class нельзя переопределить copy и когда это ломает контракт? Как сериализовать sealed-иерархию в JSON (Jackson @JsonTypeInfo/JsonSubTypes или jackson-module-kotlin)? Чем object отличается от class с companion по жизненному циклу и тестируемости?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Extension-функции и inline/reified: как работает расширение, почему его нельзя переопределить и зачем нужен reified?', 'Extension-функция компилируется в статический метод, где receiver становится первым параметром, поэтому разрешение происходит статически на этапе компиляции по объявленному типу переменной: extension нельзя переопределить, он не виртуален, и при конфликте member-метод всегда побеждает extension. Следствия: полиморфизм на extension не работает (List<Sub> вызывает extension для List, а не для Sub), private-члены receiver недоступны, а extension для nullable-receiver возможен (fun String?.isNullOrBlank()), что часто используется для безопасных операций. Неоднозначные ситуации решаются правилом «более специфичный тип и другой пакет/импорт» — неявный вызов extension из другого пакета без импорта не работает, поэтому их выносят в *Extensions.kt. extension-свойства и companion-extensions — те же статические методы, а extension внутри класса — член-расширение с доступом к состоянию класса. inline-функции подставляют тело в call site, что убирает аллокацию лямбды и позволяет non-local return; crossinline запрещает такой return, noinline выключает инлайнинг для конкретного параметра, а большие inline-функции раздувают байткод. reified доступен только в inline и позволяет то, что запрещено erasure: T::class, is T, T::class.java, typeOf<T>(), создание T через рефлексию/фабрику; классический пример — inline fun <reified T> Gson.fromJson(json: String): T. Ещё один инструмент без аллокаций — @JvmInline value class, который в большинстве случаев на JVM разворачивается в примитив и даёт type-safety без обёртки. Ограничение: reified работает только для типов без параметров на месте вызова и требует, чтобы вызывающий код был Kotlin-кодом.', 'Почему inline-функция с reified не работает через Java? Как выбрать между extension-функцией и обычным util-методом? Что произойдёт при двух extension с одинаковой сигнатурой в разных пакетах?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'JUNIOR', 'Scope-функции let/run/with/apply/also и делегирование by: что когда применять?', 'Scope-функции различаются двумя осями: what — доступ через it (let, also) или через this (run, with, apply), и что возвращает — сам объект (apply, also) или результат лямбды (let, run, with). Практические правила: apply для конфигурации объекта перед использованием (builder: request.apply { url = ...; method = POST }), also для побочных действий, не меняющих объект (логирование, валидация: obj.also { log.info(...) }), let для null-safe преобразований и локальных переменных (user?.let { send(it) }), run для блока вычислений над receiver (val x = obj.run { field + other }) или для null-safe блока (user?.run { ... }), with для нескольких операций без null-check (with(response) { println(status); body }), когда возвращаемое значение нужно по-другому. Подводный камень — вложенные scope с одинаковым this/it: читаемость падает, появляется shadowing; при вложенности лучше явно назвать it или разбить на функции. by в Kotlin — делегирование: by lazy (по умолчанию LazyThreadSafetyMode.SYNCHRONIZED, потокобезопасно через блокировку; PUBLICATION допускает конкурентную инициализацию, NONE — single-threaded самый быстрый, но небезопасный), by map (значения из Map, удобно для динамических свойств), by observable/vetoable для реакций на изменение, а также собственные делегаты через ReadOnlyProperty/ReadWriteProperty (operator fun getValue/setValue). Class delegation class Repo(private val api: Api) : Api by api генерирует делегирующие методы и позволяет переопределить только нужную часть — удобно для декораторов, кэширующих и retry-обёрток. Порядок делегирования по умолчанию берётся из делегата — например, java.io.Serializable и интерфейсы через by.', 'Почему lazy по умолчанию SYNCHRONIZED и когда NONE оправдан? Как написать свой делегат кэша? Чем apply отличается от also в отладке бага?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Корутины vs потоки: как работает suspend под капотом, что такое структурированная конкурентность и как устроена отмена?', 'suspend-функция компилируется через CPS-преобразование: к параметрам добавляется Continuation<? super T>, а тело превращается в конечный автомат с label-состояниями; когда вызывается другая suspend-функция, текущая возвращает COROUTINE_SUSPENDED и выходит из метода, не блокируя поток, а возобновление происходит вызовом continuation.resume(value) в потоке диспетчера. Диспетчеры: Dispatchers.Default (параллелизм = max(2, число ядер), CPU-bound), Dispatchers.IO (по умолчанию до 64 потоков, конфигурируется kotlinx.coroutines.io.parallelism, блокирующие вызовы), Dispatchers.Main (UI), Unconfined (не рекомендован для прод-кода); смена контекста — withContext. runBlocking блокирует поток, launch/aspect — структурная: CoroutineScope задаёт Job-иерархию, родитель ждёт детей и отменяет их при своей отмене, ошибка ребёнка по умолчанию отменяет родителя (если это не supervisorScope/SupervisorJob), coroutineScope — точка входа, аналог StructuredTaskScope в Java 21. Отмена кооперативная: корутина должна проверять isActive/ensureActive/yield или вызывать приостанавливающиеся функции с поддержкой CancellationException; Thread.sleep не отменяется, в отличие от delay. CancellationException — штатное завершение, оно не передаётся в CoroutineExceptionHandler; для launch на верхнем уровне обработчик задаётся через CoroutineExceptionHandler, для async ошибка приходит в await(). Скоуп должен быть привязан к lifecycle (viewModelScope, lifecycleScope) или к компоненту; GlobalScope в проде — антипаттерн. С Java 21 есть и третий путь: виртуальные потоки позволяют писать привычный блокирующий код, а корутины дают каналы, Flow и более тонкий контроль отмены — выбор зависит от того, нужен ли backpressure и композиция потоков или достаточно убрать блокировку.', 'Что произойдёт, если suspend-функция вызовет Thread.sleep? Как вы тестируете отмену и таймауты (withTimeout, runTest/virtual time)? Почему ошибка в async не логируется сама по себе?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Flow: cold и hot, backpressure, обработка ошибок и отмена — в чём отличия от RxJava?', 'Flow — холодный асинхронный поток: билдер flow { emit(...) } не выполняет тело до момента collect, каждый новый подписчик запускает цепочку заново, а промежуточные операторы (map, filter, take, debounce) строят декораторы. Backpressure реализован приостановкой: при медленном потребителе эмиттер просто suspend-ится, а не бросает ошибку, как старые версии RxJava; для буферизации есть buffer, conflate и collectLatest (при новом значении предыдущая обработка отменяется), а fan-out решается flatMapLatest/merge. Важное ограничение: нельзя emit из другого контекста (IllegalStateException о нарушении контекста) — для этого используют channelFlow/flowOn, где flowOn меняет контекст выше по потоку. Горячие потоки: StateFlow (всегда имеет начальное/текущее значение, conflate, повторяет последнее слепленному подписчику), SharedFlow (без начального значения, replay, буфер и onBufferOverflow), плюс shareIn/stateIn с started = WhileSubscribed(5000), чтобы не держать подписку при отсутствии потребителей. Обработка ошибок: оператор catch перехватывает исключения upstream, retry/retryWhen для повторных попыток, onCompletion для финализации, finally; исключения в downstream собираются try/catch вокруг collect. Отмена: корутина-коллектор отменяется, отмена распространяется через отменяемый контекст, суспендирующие операторы на это кооперативны; lifecycle-aware API — collectAsStateWithLifecycle/repeatOnLifecycle, иначе сбор утечёт с UI/View. В отличие от RxJava, Flow не приносит базовые операторы для горячих источников (аналог Subject есть только как SharedFlow), но интегрирован с coroutines, cancellation и Structured Concurrency, а интероп с виртуальными потоками делается через executor.asCoroutineDispatcher().', 'Чем StateFlow отличается от LiveData и почему LiveData устарел в новых проектах? Как реализовать backpressure при записи в БД батчами? Как тестировать Flow с виртуальным временем (runTest, TestDispatcher)?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Интероп Kotlin и Java: что нужно знать при совместной работе в одном сервисе?', 'Основные границы: платформенные типы (String!) теряют null-проверки, аннотации @Nullable/@NotNull из JetBrains/JSR-305 читаются компилятором и помогают, но без них нужна защита на стороне Java. Проверки non-null в Kotlin генерируют Intrinsics.checkNotNullParameter в публичных точках входа, поэтому Java-вызовы с null падают с NullPointerException в момент входа, а не позже. Для статики Kotlin-классов: @JvmStatic превращает члены companion object в реальные static-методы, @JvmField открывает поле без геттера, const val даёт константу на уровне компиляции, @JvmOverloads генерирует перегрузки для значений по умолчанию (иначе default-аргументы недоступны из Java), @Throws(someException::class) добавляет throws для checked-исключений (Java без него не сможет их отловить), @JvmName решает конфликты erasure (например, два метода с одинаковой сигнатурой после стирания типов). Дефолтные методы интерфейсов: Kotlin генерирует DefaultImpls, и чтобы получить настоящие default-методы в байткоде, применяют -Xjvm-default=all; иначе реализация интерфейса на Java не унаследует тело по умолчанию. Видимость internal в байткоде = public с mangling имени, то есть Java-код может обратиться к «внутренним» членами — это не инкапсуляция, а соглашение. Generics: из Java виден data class с copy/componentN, значения по умолчанию недоступны без @JvmOverloads, Unit транслируется как void, а Kotlin бросает только unchecked-исключения, поэтому работа с Java-API с checked-исключениями требует @Throws. Коллекции: List из Kotlin — это java.util.List, изменяемость определяется интерфейсом только на уровне компилятора Kotlin (List vs MutableList), из Java их можно менять; зато read-only-типы не защищают от мутации, нужна копия. Kotlin-функциональные типы не являются SAM-интерфейсами напрямую, но SAM-конверсия для Java-интерфейсов работает, а лямбды Kotlin передаются в Java как FunctionN.', 'Как вы обеспечивали корректный контракт с Java-модулем (аннотации, тесты, спецификации)? Что произойдёт при вызове Kotlin-метода с default-параметром из Java без @JvmOverloads? Как избежать name mangling в Spring Data?' from categories where slug = 'kotlin';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Что такое IoC и DI в Spring и какие способы внедрения зависимостей есть? Какой предпочтительнее и почему?', 'IoC — это принцип, при котором создание и связывание объектов отдаётся контейнеру, а DI — конкретный механизм: зависимости передаются объекту извне, а не создаются им самим. Spring поддерживает внедрение через конструктор, через сеттер и через поле аннотацией @Autowired. Конструкторное внедрение предпочтительно: зависимости можно объявить final, объект всегда создаётся в валидном состоянии, класс тестируется без контейнера обычным new, а циклическая зависимость проявляется сразу на старте как BeanCurrentlyInCreationException, а не как NullPointerException в рантайме. Начиная со Spring 4.3 единственный конструктор не требует @Autowired вовсе. Field injection удобен в тестовых бинах, но скрывает зависимости, не даёт final и ломает инкапсуляцию. Setter injection оправдан для опциональных зависимостей или когда значение нужно переустановить после создания. Циклы контейнер частично разруливает через трёхуровневый кэш singleton-бинов, но Spring Boot 2.6+ по умолчанию их запрещает (spring.main.allow-circular-references=false), и это правильно. На практике цикл я разрываю вынесением общей логики в третий бин или @Lazy на одну из зависимостей.', 'Что именно лежит в трёхуровневом кэше singleton-бинов и как это позволяет отдать недосозданный бин другому бину?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Какие scope бинов есть в Spring и что произойдёт, если singleton инжектит prototype-бин?', 'По умолчанию бин singleton: один экземпляр на ApplicationContext. prototype создаёт новый объект на каждый getBean() или на каждое место внедрения, причём Spring не управляет его уничтожением — @PreDestroy не вызовется, ресурсы придётся освобождать самому. Веб-scope request, session, application и websocket работают только в web-aware контексте и реализуются через scoped-прокси (ScopedProxyMode.TARGET_CLASS): в singleton внедряется прокси, который при каждом вызове достаёт реальный бин текущего запроса. Классическая ловушка: если singleton получает prototype через конструктор, prototype создаётся ровно один раз вместе с singleton. Лечится @Lookup-методом (CGLIB переопределяет метод и возвращает свежий бин), инъекцией ObjectProvider/ObjectFactory с вызовом getObject() в момент использования или scoped-прокси. Свой scope пишут как реализацию Scope и регистрируют через registerScope — например, для мультитенантности или hot-reload тома. Для тяжёлых ресурсов вроде DataSource правильный выбор — singleton плюс пул соединений, а prototype оправдан только для stateful-объектов, которые не должны разделяться между потоками.', 'Почему @Lookup не сработает без CGLIB и как выглядит рабочая связка @Lookup с ObjectProvider?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Опишите полный жизненный цикл бина в Spring. Когда создаются прокси и чем опасен prototype?', 'Порядок такой: контейнер читает BeanDefinition, при getBean вызывает конструктор (instantiate), затем populate — внедрение зависимостей и обработка Aware-интерфейсов (BeanNameAware, BeanFactoryAware, ApplicationContextAware). Далее BeanPostProcessor.postProcessBeforeInitialization, потом @PostConstruct, afterPropertiesSet() из InitializingBean и init-method из @Bean(initMethod=...), затем postProcessAfterInitialization — именно здесь AOP-инфраструктура (AbstractAutoProxyCreator) заворачивает бин в прокси. После этого готовый бин лежит в singleton-кэше, а при закрытии контекста вызываются @PreDestroy, DisposableBean.destroy() и destroyMethod. Критично: для prototype-бинов destroy-фаза не вызывается, потому что Spring не хранит на них ссылки, поэтому закрытие ресурсов надо делать вручную или через собственный реестр. Ещё нюанс: BeanPostProcessor создаются раньше всех обычных бинов и сами не проходят полный цикл постобработки, поэтому если ваш BPP зависит от другого BPP, Spring предупредит, что бин не обрабатывается всеми постпроцессорами. Практический вывод: своё оборачивание в прокси делайте в postProcessAfterInitialization с проверкой типа или аннотации, а не в init-методе, иначе получите внутренний прокси, который не действует на внешние вызовы. Ещё есть SmartInitializingSingleton — вызывается после готовности всех singleton-бинов.', 'Почему бин-постпроцессор, зависящий от проксированного бина, получит необработанный оригинал и как это заметить?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Чем BeanFactoryPostProcessor отличается от BeanPostProcessor и какие механизмы Spring реализованы через каждый из них?', 'BeanFactoryPostProcessor работает на этапе BeanDefinition, то есть до создания самих бинов, и может менять их метаданные: так работают PropertySourcesPlaceholderConfigurer (подстановка ${...}) и ConfigurationClassPostProcessor (разбор @Configuration, @ComponentScan, @Import). BeanPostProcessor работает на этапе инстанцирования конкретного бина своими двумя методами — before и after initialization, и через него Spring реализует @Autowired (AutowiredAnnotationBeanPostProcessor), @PostConstruct, Bean Validation, @Async, @Scheduled, @Retryable и AOP-прокси. Порядок постпроцессоров регулируется @Order/Ordered; например, прокси для @Async должно применяться в правильной последовательности относительно других советов, поэтому у таких BPP выставляются продуманные precedence. Особая разновидность — BeanDefinitionRegistryPostProcessor, который может дописывать новые определения бинов; именно через него Spring сканирует пакеты. Если BPP спавнится слишком рано и зависит от других BPP, контейнер пишет предупреждение is not eligible for getting processed by all BeanPostProcessors, и такой бин не будет проксирован. В проекте я использовал BPP для аудита бинов с кастомной аннотацией и для обогащения бинов значениями из Vault. Ещё на этапе старта есть SmartInitializingSingleton и слушатели ApplicationReadyEvent — их удобно использовать вместо @PostConstruct, когда нужен доступ ко всем готовым бинам.', 'Чем SmartInitializingSingleton отличается от @PostConstruct и почему ApplicationRunner иногда предпочтительнее обоих?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как работает автоконфигурация Spring Boot и что такое стартеры? Как отладить, почему конфигурация не применилась?', '@SpringBootApplication объединяет @SpringBootConfiguration, @ComponentScan и @EnableAutoConfiguration. Последняя через AutoConfigurationImportSelector читает список классов-кандидатов из META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports (до Boot 2.7 — spring.factories) и фильтрует их аннотациями условий: @ConditionalOnClass, @ConditionalOnMissingClass, @ConditionalOnBean, @ConditionalOnMissingBean, @ConditionalOnProperty, @ConditionalOnWebApplication, @ConditionalOnResource. Порядок применения задаётся @AutoConfiguration после/до и @AutoConfigureAfter/@AutoConfigureBefore, потому что условия на бины оцениваются уже по факту регистрации. Пользовательские @Configuration обрабатываются раньше автоконфигураций, поэтому @ConditionalOnMissingBean видит ваш бин и отключает дефолт — на этом построено переопределение DataSource или ObjectMapper. Стартер — это агрегатор зависимостей без кода: spring-boot-starter-web приносит spring-web, spring-webmvc, Tomcat и Jackson, а стартеры Spring Data/JPA добавляют Hibernate, HikariCP, Spring Data. Для отладки запускают приложение с --debug или включают logging.level.org.springframework.boot.autoconfigure=DEBUG и смотрят ConditionEvaluationReport: какие конфигурации применились, какие нет и по какому условию. Свою автоконфигурацию оформляют как @AutoConfiguration-класс со списком в AutoConfiguration.imports и обязательными @Conditional*, чтобы библиотека не ломала чужое приложение. Ещё: @ConfigurationProperties в Spring Boot 3 требует @EnableConfigurationProperties или @ConfigurationPropertiesScan, поэтому бин без этого просто не создаётся.', 'Почему @ConditionalOnMissingBean не сработает, если ваш бин объявлен в другой автоконфигурации без @AutoConfigureBefore?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Зачем @Configuration проксируется через CGLIB и как правильно использовать @Profile и proxyBeanMethods?', '@Configuration по умолчанию оборачивается CGLIB-подклассом (proxyBeanMethods=true), чтобы вызовы @Bean-методов внутри класса не создавали новые объекты, а возвращали уже зарегистрированный бин из контекста. Если поставить proxyBeanMethods=false или вместо @Configuration использовать @Component с @Bean, прокси не создаётся: так легче для AOT/нативных образов и быстрее на старте, но прямые вызовы @Bean-методов дадут новые экземпляры и потеряют singleton-семантику. Проксирование не работает, если класс или метод final/private/static — это частая причина странного поведения и молчаливого дублирования бинов. @Profile вешается на @Configuration, @Bean или @Component, а включается через spring.profiles.active, spring.profiles.include или @ActiveProfiles в тестах, поддерживаются выражения вида prod & !legacy. Я предпочитаю не условную логику внутри одного класса, а отдельные классы конфигурации на окружение (ProdDataSourceConfig, LocalDataSourceConfig) — это читаемее и проверяемо тестами. В CI профиль передаётся переменной SPRING_PROFILES_ACTIVE, а секреты — из Kubernetes Secret или Vault, а не из репозитория. В Boot 2.4+ профилям на смену приходит Config Data API с application-{profile}.yml, но семантика остаётся той же.', 'Что именно произойдёт, если @Configuration-класс сделать final, и как это выглядит в логах на старте приложения?' from categories where slug = 'spring-core';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как Spring AOP создаёт прокси и когда он использует JDK dynamic proxy, а когда CGLIB? Какие ограничения это накладывает?', 'Spring AOP работает на прокси: контейнер создаёт объект-обёртку, которая перехватывает вызовы и применяет советы до/после/вокруг. Если бин реализует интерфейсы и proxyTargetClass=false, используется JDK dynamic proxy — генерируется класс, реализующий те же интерфейсы, поэтому внедрять зависимость нужно по интерфейсу, иначе получите BeanNotOfRequiredTypeException. CGLIB генерирует подкласс самого класса в рантайме и переопределяет его не-final методы; Spring Boot по умолчанию выставляет spring.aop.proxy-target-class=true, то есть практически всегда работает CGLIB. Ограничения CGLIB: final-класс не проксируется вообще, final/private/static методы не перехватываются, поэтому @Transactional или @Async на них молча не работает. Дополнительный нюанс: конструкторы не перехватываются, так как прокси создаётся после инстанциирования целевого объекта. Если нужны вызовы внутри класса или private-методы, применяют AspectJ load-time weaving вместо прокси, но это редко оправданная сложность. В отладке я проверяю AopUtils.isAopProxy(bean), isJdkDynamicProxy и AopUtils.getTargetClass(bean), чтобы понять, что реально лежит в контексте.', 'Почему при JDK-прокси Spring не может внедрить бин по конкретному классу и как быстро это диагностировать в стеке ошибки?' from categories where slug = 'spring-aop-transactions';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Что такое self-invocation и почему @Transactional или @Cacheable внутри того же класса не срабатывают?', 'Аннотации @Transactional, @Async, @Cacheable и @Retryable реализованы через прокси, и срабатывают только когда вызов приходит извне, через прокси-объект. Внутренний вызов this.saveInternal() идёт напрямую в целевой объект, минуя прокси, поэтому совет не применяется — компилятор об этом не скажет, и транзакция тихо не откроется. Это одна из самых частых ошибок на code review: @Transactional-метод, вызываемый из другого метода того же класса, работает без транзакции. Решения: вынести метод в отдельный бин (правильный и проверяемый вариант), самоинъекция прокси через @Autowired на себя или ApplicationContext, @Lazy-инъекция себя, либо программный TransactionTemplate. AspectJ weaving снимает проблему полностью, но усложняет сборку и требует spring-aspects, поэтому в обычном сервисе не нужен. Дополнительно: метод private или класс final не будут проксированы CGLIB, так что даже внешний вызов ничего не даст. Практическое правило — если в классе есть @Transactional, все публичные методы этого класса должны вызываться снаружи, а вложенные шаги лучше выделять в отдельные бины по ответственности.', 'Как настроить AspectJ load-time weaving и в каких случаях он реально оправдан против прокси?' from categories where slug = 'spring-aop-transactions';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Разберите propagation в @Transactional. Чем REQUIRED отличается от REQUIRES_NEW и NESTED?', 'Propagation определяет поведение метода, который вызывается внутри уже открытой транзакции. REQUIRED, значение по умолчанию, присоединяется к существующей транзакции или создаёт новую, если её нет. REQUIRES_NEW приостанавливает внешнюю транзакцию и открывает независимую со своим соединением, поэтому её коммит сохранится даже при откате внешней. NESTED создаёт savepoint внутри текущей транзакции, но JPA/Hibernate его не поддерживает, и на практике этот режим часто падает или ведёт себя неожиданно. SUPPORTS работает в транзакции при её наличии и без неё в противном случае, NOT_SUPPORTED приостанавливает транзакцию, MANDATORY требует её наличия и падает без неё, NEVER падает при наличии транзакции. Типовой бизнес-кейс для REQUIRES_NEW — аудит или журнал, который обязан сохраниться даже при откате бизнес-операции, но надо помнить про свой коннект из пула: при пуле в 10 соединений и 10 параллельных внешних транзакциях внутренние REQUIRES_NEW повиснут на таймауте. Ещё важно, что REQUIRES_NEW не работает при self-invocation, а границы транзакции лучше держать на уровне сервисного метода, чтобы не растягивать удержание блокировок. Для частичного отката на JPA вместо NESTED проще разбить операцию на отдельные шаги с компенсацией или проектировать логику так, чтобы savepoint не требовался.', 'Почему NESTED ломается на Hibernate и что использовать вместо него для частичного отката?' from categories where slug = 'spring-aop-transactions';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как работают isolation и правила отката в @Transactional и что реально делает readOnly=true?', 'Isolation соответствует уровням SQL: READ_UNCOMMITTED, READ_COMMITTED (дефолт PostgreSQL и Oracle), REPEATABLE_READ (дефолт MySQL InnoDB) и SERIALIZABLE, и определяет защиту от dirty read, non-repeatable read и phantom read. В PostgreSQL REPEATABLE_READ реализован как snapshot isolation, поэтому фантомов тоже нет, но появляется ошибка could not serialize access due to concurrent update, которую нужно ловить и ретраить. Правила отката по умолчанию: RuntimeException и Error откатывают транзакцию, checked Exception — нет; это меняется через rollbackFor и noRollbackFor, и забытый rollbackFor с checked-исключением даёт записанные данные при ошибке. readOnly=true переводит Hibernate в FlushMode.MANUAL, убирает dirty checking, позволяет роутить запрос на реплику в схеме read/write splitting и включает оптимизации драйвера, но это не запрет записи: явный INSERT в такой транзакции может пройти. Ещё стоит помнить, что атрибут timeout задаёт лимит в секундах на транзакцию и по его истечении летит TransactionTimedOutException, а не таймаут HTTP. Всё это работает только через прокси, поэтому self-invocation и private-методы снова вне игры. На практике для сервисов чтения readOnly=true — хорошая гигиена, а уровень изоляции выше READ_COMMITTED я трогаю только осознанно, под конкретную конкурентную проблему.', 'Какая аномалия реально остаётся при REPEATABLE_READ в PostgreSQL и как её обрабатывать в сервисном коде?' from categories where slug = 'spring-aop-transactions';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Что такое проблема N+1 в JPA и как вы её находите и лечите?', 'N+1 — это когда один запрос достаёт список сущностей, а Hibernate затем делает отдельный SELECT на каждую lazy-связь, и вместо одного запроса получается N+1. Находится это по логам SQL (spring.jpa.show-sql=true плюс org.hibernate.SQL/orm.jdbc.bind) или по статистике при hibernate.generate_statistics=true: смотрят query count и prepared statements на один вызов. В тестах удобно ставить datasource-proxy или использовать Hibernate SQLStatementCountValidator, чтобы падать на регрессии по числу запросов. Лечение в порядке предпочтения: hibernate.default_batch_fetch_size=50 грузит lazy-связи пачками через IN и убирает почти все N+1 без изменения запросов; @EntityGraph(attributePaths = {...}) или JPQL join fetch подтягивает нужное для конкретного use case; DTO-проекции вообще не тянут сущности. С join fetch надо осторожно: две коллекции в одном запросе дают MultipleBagFetchException, лечится Set вместо List или двумя запросами. И отдельно про пагинацию: Pageable плюс join fetch даёт предупреждение HHH000104 и in-memory pagination, поэтому делают двухшаговый запрос — сначала id с пагинацией, потом fetch по списку id. В реальном сервисе связки batch_fetch_size плюс точечные entity graph хватает, чтобы убрать N+1 полностью.', 'Почему join fetch вместе с Pageable приводит к HHH000104 и как построить пагинацию корректно без in-memory сортировки?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'LAZY и EAGER в JPA: где дефолты, откуда LazyInitializationException и почему open-in-view это антипаттерн?', 'Для коллекций @OneToMany и @ManyToMany дефолт LAZY, для @ManyToOne и @OneToOne — EAGER, что часто тянет лишние select''ы в графе. LAZY отдаёт прокси-коллекцию (PersistentBag, PersistentCollection), которая инициализируется при первом обращении к ней. LazyInitializationException возникает, когда обращаются к такой связи вне открытой сессии — типично в контроллере при сериализации Jackson или после закрытия транзакции. Правильное лечение — не переключать на EAGER, а держать доступ к данным внутри границы транзакции: @Transactional на сервисном методе, маппинг в DTO там же, а под конкретный сценарий — fetch join или entity graph. Open Session in View (spring.jpa.open-in-view=true) включён в Spring Boot по умолчанию и продлевает сессию на весь HTTP-запрос: он маскирует N+1 и держит соединение из пула всё время ответа, поэтому я его отключаю с самого начала (spring.jpa.open-in-view=false) и это же рекомендует документация. Отдельная ловушка — @OneToOne(fetch = LAZY) без @MapsId: на владеющей стороне Hibernate не знает, существует ли объект, и всё равно идёт в БД либо возвращает прокси-обёртку. Практический принцип: все связи LAZY, а нужные данные подтягиваются явными запросами под конкретную операцию, тогда граф загрузки предсказуем.', 'Почему @OneToOne(fetch = LAZY) не работает без @MapsId и как проверить, что связь действительно ленивая?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Перечислите состояния сущности в JPA и подводные камни merge, dirty checking и getReference.', 'Состояний четыре: transient — объект создан, id нет, связи с сессией нет; managed — объект в persistence context, изменения отслеживаются dirty checking и уходят в БД на flush или commit; detached — объект был managed, но сессия закрыта, типично после завершения транзакции; removed — помечен на удаление до flush. Основные методы EntityManager: persist (сделать transient managed), merge (скопировать состояние detached-объекта в managed и вернуть другой инстанс), remove, refresh, find и getReference (последний возвращает прокси без запроса к БД). Классическая ловушка merge: если у detached-сущности lazy-связь не загружена, при merge она может подтянуться либо затирается null''ом, что приводит к потере данных во внешних ключах. Dirty checking объясняет, почему явный save() в транзакции не нужен, но он же причина неожиданных UPDATE из-за изменения поля мимоходом. equals/hashCode по id опасно для transient-сущностей, поэтому в банковских моделях я предпочитаю бизнес-ключ или сравнение по ссылке в пределах сессии. Для bulk-update через @Modifying нужно ставить clearAutomatically=true, иначе персистентный контекст держит устаревшие сущности и отдаёт их как актуальные.', 'Что вернёт merge для detached-сущности и почему после него нельзя продолжать работать со старым инстансом?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как делать эффективные проекции и JDBC-батчинг в Spring Data, и почему IDENTITY мешает батчам?', 'Проекции в Spring Data бывают интерфейсные, class-based DTO через конструктор и динамические. Закрытая интерфейсная проекция, где геттеры совпадают с полями, транслируется в узкий SELECT, а открытая с @Value и SpEL грузит сущность целиком и вычисляет значение в памяти — на тысячах строк это заметная разница. Для отчётов и списков всегда правильнее DTO-проекция: нет managed-сущностей, нет lazy-проблем, меньше данных по сети. Батчинг включается hibernate.jdbc.batch_size (например, 30) вместе с hibernate.order_inserts=true и hibernate.order_updates=true, иначе Hibernate перемежает INSERT и UPDATE и пакеты не работают; для MySQL добавляют rewriteBatchedStatements=true в драйвере. Ключевой момент: при GenerationType.IDENTITY Hibernate не может батчить, потому что должна получить сгенерированный id после каждого INSERT, и делает по одному statement — нужен SEQUENCE с pooled или pooled-lo оптимизатором (allocationSize 50). Проверяется эффект по статистике hibernate.generate_statistics: смотрят количество JDBC statements и успешных batch''ей. Ещё стоит помнить, что flush и clear между порциями (или StatelessSession) нужны, чтобы персистентный контекст не рос на сотнях тысяч строк при загрузке выписок.', 'Как по Statistics понять, что батчинг реально работает, и какие ещё настройки Hibernate мешают пакетам?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Кэши L1 и L2 в Hibernate, оптимистическая и пессимистическая блокировка, @Version — как это работает вместе?', 'L1 — это persistence context конкретной сессии, он всегда включён: два find по одному id в пределах транзакции вернут один и тот же объект, а кэш невидим другим транзакциям и умирает вместе с EntityManager. L2 — кэш уровня SessionFactory, включается hibernate.cache.use_second_level_cache=true с провайдером (Ehcache, Caffeine через JCache, Redis) и требует @Cache с usage READ_ONLY/READ_WRITE и стратегией конкурентности; он инвалидируется при обновлении через Hibernate, но не видит bulk-update и нативные запросы, из-за чего легко получить рассинхрон, поэтому в 90% случаев я кэширую DTO на уровне сервиса через @Cacheable и явный TTL. Оптимистическая блокировка — это @Version: Hibernate добавляет в UPDATE условие where id = ? and version = ?, при нулевом числе обновлённых строк бросает ObjectOptimisticLockingFailureException, а версия в объекте инкрементируется. Пессимистическая — LockModeType.PESSIMISTIC_READ/PESSIMISTIC_WRITE, транслируется в select ... for update, держит блокировку строки до конца транзакции и годится только для коротких критических секций вроде изменения остатка. Пессимистическая блокировка на длинной транзакции — прямой путь к deadlock''ам и таймаутам, поэтому дефолт должен быть оптимистический с обработкой конфликта. В нашем случае при 5 RPS конфликты почти не возникают, но обработка OptimisticLockingFailureException обязательна: локальный retry на 2-3 попытки с backoff, а наружу — 409 Conflict, если конфликт не разрешился.', 'Почему @Version не защитит от потери обновления при bulk-update или нативном SQL и как это лечить?' from categories where slug = 'spring-data-jpa';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Когда выбирать Spring MVC, а когда WebFlux? Оправдан ли переход на WebFlux для нагрузки в 5 RPS?', 'Spring MVC — синхронный servlet-стек: один поток на запрос из пула Tomcat (по умолчанию 200), блокирующие вызовы JDBC и JPA для него нормальны. WebFlux — реактивный стек на Reactor и Netty с event loop, где потоки не блокируются, а backpressure встроен в поток данных. Выигрыш от реактивности появляется только на большом числе одновременных медленных I/O-операций: API-шлюзы, агрегаторы, стриминг, WebSocket/SSE с тысячами соединений. Если в приложении JPA, то реактивность не работает без перехода на R2DBC, а обёртка блокирующего кода в Mono.fromCallable с subscribeOn(boundedElastic) съедает весь смысл и добавляет скрытую нагрузку. При 5 RPS уходить на WebFlux не нужно: это усложнение отладки, стеков ошибок и совместимости библиотек без выигрыша. Правильный путь для Java 21 — Spring MVC с включёнными виртуальными потоками (spring.threads.virtual.enabled=true), что даёт почти реактивную пропускную способность на блокирующем коде без смены парадигмы. Реактивный стек оправдан, если сервис сам по себе шлюз (Spring Cloud Gateway реактивен) или держит долгие соединения, а не потому что «WebFlux современнее». Мой ответ на интервью: MVC по умолчанию, WebFlux — под конкретный профиль нагрузки с доказанной пользой.', 'Что произойдёт, если в WebFlux-цепочке вызвать блокирующий JPA-метод без subscribeOn, и как это проявляется в метриках?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Чем Filter отличается от HandlerInterceptor и куда что вешать?', 'Servlet Filter работает до DispatcherServlet, оборачивает весь запрос и ответ, умеет читать тело и заголовки, видит ошибки, но не имеет доступа к HandlerMethod и не сработает для внутренних forward''ов. HandlerInterceptor — механизм Spring внутри DispatcherServlet: preHandle, postHandle, afterCompletion, и он видит конкретный HandlerMethod, то есть может проверить аннотацию или роль на методе. Порядок такой: Filter, потом DispatcherServlet, затем preHandle, контроллер, postHandle, afterCompletion и только потом выход из Filter. На практике Filter (или FilterRegistrationBean с order) — это request-id и MDC, логирование, CORS, rate limiting, аутентификация через Spring Security SecurityFilterChain; Interceptor — проверки прав на метод, аудит вызова, обогащение модели. Важное отличие в обработке ошибок: исключение из Filter не попадёт в @ControllerAdvice, потому что Advice работает внутри DispatcherServlet через HandlerExceptionResolver, поэтому в фильтре либо пишут ответ сами, либо делегируют в ErrorController, либо настраивают AuthenticationEntryPoint/AccessDeniedHandler. Ещё есть ResponseBodyAdvice и HandlerMethodArgumentResolver — следующий уровень, где удобно единообразно обогащать ответы и резолвить аргументы. Не стоит превращать фильтр в бизнес-логику: он видит всё, включая статику и health-check.', 'Как отдать ошибку из фильтра в том же формате, что и @ControllerAdvice, не дублируя логику?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы организуете обработку ошибок через @ControllerAdvice и что такое ProblemDetail?', '@RestControllerAdvice даёт глобальные @ExceptionHandler''ы, @InitBinder и @ModelAttribute, через него строится единый формат ошибок для всех контроллеров. Обязательный минимум — обработать MethodArgumentNotValidException и BindException (валидация тела и DTO), ConstraintViolationException (валидация @RequestParam и @PathVariable при @Validated на классе), HttpMessageNotReadableException (битый JSON), MethodArgumentTypeMismatchException и собственные бизнес-исключения с маппингом в 400/404/409. Наружу лучше отдавать ProblemDetail по RFC 7807 (type, title, status, detail, instance) с дополнительным массивом errors для полей, включив spring.mvc.problemdetails.enabled=true — этот формат понимают и фронт, и шлюз. Обязательно следить, чтобы стектрейс и текст SQL не уходили клиенту: наружу только обезличенное сообщение, а внутри — лог с traceId, чтобы по нему найти полный контекст в Loki или Kibana. Логирование надо разделять: 5xx — ERROR со стеком, 4xx и бизнес-ошибки — WARN без стека, иначе логи и алерты теряют смысл. Отдельная тема — ошибки вне MVC: исключение из фильтра безопасности ловит не Advice, а AuthenticationEntryPoint и AccessDeniedHandler, и их тоже нужно настраивать в единый формат. Ещё важно не глотать ошибку: если Advice возвращает 500 с общим текстом, обязательно логируется причина и метрика error rate по типам.', 'Почему AccessDeniedException из Spring Security не всегда попадает в @ControllerAdvice и что нужно настроить вместо него?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как вы делаете валидацию входных данных и как обеспечить идемпотентность POST-запросов?', 'Валидация формальных ограничений — Jakarta Bean Validation: @NotNull, @Size, @Pattern, @Email, каскад через @Valid на вложенных объектах, а @Valid на @RequestBody в контроллере включает проверку. Для @RequestParam и @PathVariable нужен @Validated на классе контроллера, а группы валидации (интерфейсы-маркеры OnCreate/OnUpdate) позволяют разное поведение для создания и обновления. Сложные проверки (БИК, ИНН с контрольной суммой, номер счёта) пишутся как свои ConstraintValidator, а не как хрупкий regex; бизнес-валидация (лимиты, доступность счёта) — уже в сервисе, потому что требует данных из БД. Идемпотентность POST: по HTTP POST не идемпотентен, поэтому либо клиент передаёт Idempotency-Key, либо используется естественный бизнес-ключ. С Idempotency-Key сервер хранит ключ и результат в Redis или таблице с TTL (обычно 24 часа) и на повтор возвращает сохранённый ответ, не создавая дубль; запись ключа делается атомарно (SETNX или уникальный индекс), иначе гонка двух одновременных запросов создаст двукратное списание. С естественным ключом работает уникальный индекс в БД плюс обработка DataIntegrityViolationException с возвратом существующей сущности или 409. В Kafka-потребителях та же логика: дедуп по event_id в таблице processed_messages с первичным ключом. Ключ разумно привязывать к хэшу тела запроса, иначе повтор с другим payload молча перезапишет смысл операции.', 'Как избежать гонки, когда два одинаковых запроса с одним Idempotency-Key приходят строго одновременно?' from categories where slug = 'spring-mvc';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Разберите OAuth2 Authorization Code Flow с PKCE: как он работает и от чего защищает PKCE?', 'Authorization Code Flow для браузерных и мобильных клиентов устроен так: клиент редиректит пользователя на /realms/{realm}/protocol/openid-connect/auth с параметрами response_type=code, client_id, redirect_uri, scope, state, nonce и code_challenge. Пользователь аутентифицируется в Keycloak, и тот возвращает одноразовый код на redirect_uri. Клиент обменивает код на токены через POST /token с grant_type=authorization_code, code, redirect_uri, client_id и code_verifier. PKCE защищает публичных клиентов от перехвата кода: code_challenge = S256(code_verifier), и при обмене Keycloak сверяет verifier с challenge, поэтому украденный код без verifier бесполезен. state защищает от CSRF на редиректе, nonce сверяется при валидации id_token и защищает от подмены токена. В Keycloak клиент настраивается как public с обязательным PKCE S256, а для SPA лучше применять BFF-паттерн, чтобы refresh-токен не хранился в браузере. Код — это не токен: access-токен короткий, а обмен кода всегда происходит по back-channel, поэтому в логах он не должен появляться. В нашей внутренней системе вход идёт через Keycloak с федерацией с AD/LDAP, а шлюз (Spring Cloud Gateway) хранит сессию и проксирует вызовы с токеном.', 'Что произойдёт, если у публичного клиента отключить PKCE и атакующий перехватит redirect с кодом?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как организовать безопасность сервис-сервис: client credentials, секреты, проверка на стороне ресурс-сервера?', 'Client Credentials — grant без участия пользователя: сервис A аутентифицируется в Keycloak своим client_id и client_secret и получает access-токен для сервиса B. В Keycloak для этого включаются Confidential client, Service Accounts Enabled и роли service-account, а также маппер audience, чтобы в aud попал целевой сервис, иначе корректно настроенный ресурс-сервер отклонит токен. Секрет нельзя держать в коде и git: только Kubernetes Secret или Vault с ротацией, а лучше вообще уйти от симметричного секрета к private_key_jwt (подпись client assertion JWT) или mTLS между сервисами. Сервис B валидирует подпись по JWKS, сверяет iss, exp и nbf с допустимым clock skew, проверяет aud/azp и требуемые scope или роли — без проверки aud токен, выданный другому клиенту того же realm, пройдёт, и это типичная дыра. Spring-настройка: spring-boot-starter-oauth2-resource-server с issuer-uri, JwtDecoder сам тянет JWKS и кэширует ключи по kid. Если downstream должен соблюдать права пользователя, используют token relay (проброс access-токена), а для вызовов от имени пользователя с сужением прав — token exchange по RFC 8693. Пользовательский токен не стоит переиспользовать для служебных вызовов вроде отчётности: это ломает аудит и расширяет поверхность атаки.', 'Почему отсутствие проверки aud делает валидацию токена неполной и как это воспроизвести в тесте?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Из чего состоит JWT и что именно нужно проверять при валидации токена Keycloak?', 'JWT — это header.payload.signature в base64url: header с alg и kid, payload со клеймами и подпись. Keycloak по умолчанию подписывает RS256, поэтому для проверки достаточно публичного ключа из /realms/{realm}/protocol/openid-connect/certs, а приватный не покидает сервер. В payload важны iss, sub, aud, exp, iat, nbf, jti, azp, scope, preferred_username, а также realm_access.roles и resource_access.{client}.roles, где лежат роли. Проверять нужно строго по шагам: подпись и kid по JWKS (Spring Security делает это сам и кэширует ключи), exp и nbf с допустимым clock skew 30-60 секунд, iss должен точно совпадать с эмитентом, aud должен содержать ваш сервис или клиент. Значение alg обязано входить в whitelist (никакого none и никакой симметрики там, где ожидается RS256), иначе возможна подмена алгоритма. Парсить токен без проверки подписи — грубая ошибка, которая открывает возможность подделать роли. После валидации роли из realm_access нужно конвертировать в GrantedAuthority через JwtAuthenticationConverter (префиксы ROLE_ и SCOPE_), иначе @PreAuthorize(hasRole(''ADMIN'')) не сработает. Клеймы вроде tenant и подразделения использовать для изоляции данных, но только как дополнение к проверке владения ресурсом на уровне сервиса.', 'Как поддержать ротацию ключей в Keycloak, чтобы сервис не падал и не кэшировал JWKS навсегда?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как работают refresh-токены и разграничение доступа ролями и scope в связке Spring Security и Keycloak?', 'Access-токен короткий (5-15 минут), refresh-токен длинный и в Keycloak ротируется: при использовании включают Refresh Token Rotation, старый refresh инвалидируется, а для фоновых долгих интеграций выдают отдельный offline-токен через scope offline_access. Хранить refresh нужно вне досягаемости JS: в HttpOnly Secure SameSite=Strict cookie, а надёжнее — вообще не отдавать токены в браузер, а держать сессию на сервере в BFF-паттерне. В Spring этот цикл закрыт OAuth2AuthorizedClientManager и OAuth2AuthorizedClientService: клиент сам обновляет истёкший access-токен, а для WebClient есть ServletOAuth2AuthorizedClientExchangeFilterFunction. В Keycloak роли двух уровней — realm roles (глобальные) и client roles (специфичные для клиента), плюс composite roles и группы; scope в OAuth2 — это сужение выдаваемых клеймов и разрешений клиента, а не бизнес-роль. Поэтому разграничение доступа я строю на ролях (realm_access и resource_access), а scope использую для аудитории и узких разрешений вроде SCOPE_documents.read. Spring-настройка проста: starter-oauth2-resource-server плюс issuer-uri, а тонкие правила — через @EnableMethodSecurity и @PreAuthorize, тогда как в SecurityFilterChain остаются только грубые permitAll/authenticated. Legacy-адаптер keycloak-spring-security-adapter из Boot 3 удалён и не нужен: Keycloak — обычный OIDC-провайдер.', 'Чем пользовательский refresh-токен отличается от offline_access на практике и какие подводные камни у второго?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как правильно разграничивать права: роли, scope, @PreAuthorize — и не допустить использования пользовательского токена для служебных вызовов?', 'В SecurityFilterChain задаются только грубые правила: permitAll для /actuator/health и метрик с ограничением сети, authenticated для остального и отдельная защита management-эндпоинтов, потому что /actuator/env и /actuator/heapdump наружу отдавать нельзя. Вся тонкая логика — @EnableMethodSecurity и @PreAuthorize на методах сервиса, где можно комбинировать проверки: hasAuthority(''SCOPE_documents.write''), hasRole(''OPERATOR'') и собственные bean-выражения вида @authz.canEdit(#id). Роль — атрибут субъекта (кто ты), scope — делегированное клиенту разрешение (что разрешено этому приложению), и смешивать их в одну кучу не стоит: для внутреннего API я привязываю права к ролям realm/client, а scope держу узким и проверяю на уровне операций. Проверка владения ресурсом не выражается токеном, поэтому на уровне сервиса обязательно сверяется sub или tenant с владельцем сущности, иначе получается IDOR при валидном токене. Для служебных вызовов используется client credentials, а пользовательский токен не должен переиспользоваться для регламентных операций, иначе аудит теряет смысл и права пользователя случайно распространяются на системные действия. Если downstream обязан применять права пользователя, используется token relay или token exchange с сужением scope, а не передача произвольных заголовков с ролями. Доверять ролям из заголовков, присланных другим сервисом в обход подписи, нельзя ни в каком варианте.', 'В чём разница между token relay и token exchange по RFC 8693 и когда нужен именно второй?' from categories where slug = 'spring-security';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как определять границы микросервисов и по каким признакам понять, что граница выбрана неверно?', 'Границы определяются по бизнес-возможностям и bounded context из DDD, а не по слоям и не по таблицам: у сервиса должна быть одна причина меняться, одна команда-владелец и собственные данные. Обязательное следствие — database per service: транзакции внутри сервиса локальные, а межсервисные взаимодействия идут через API и события с согласованностью в итоге. Признаки плохих границ: общая база, сервис-обёртка над одной CRUD-таблицей, чатти-вызовы пяти сервисов на один экран и ситуация, когда любой релиз меняет все сервисы сразу — это распределённый монолит. Ещё сигнал — постоянно растущий внутренний API между двумя сервисами: значит, их либо нужно объединить, либо резать иначе. При этом не каждый модуль заслуживает отдельный сервис: я бы сначала делал модульный монолит с чёткими модульными границами, а выделял процесс, когда есть отдельная команда, отдельный цикл релиза, отличающаяся нагрузка или изоляция по требованиям безопасности и персональным данным. В нашей системе 8-10 сервисов, из которых часть — консьюмеры Kafka, и это оправдано потому, что области правда разные: заявки, документы, уведомления, интеграции. Размер сервиса не самоцель: важнее изоляция изменений и возможность команды работать независимо.', 'Когда вы бы объединили два сервиса обратно и как это сделать технически без большого переписывания?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как выбирать между синхронным и асинхронным взаимодействием сервисов?', 'Синхронный вызов (REST или gRPC) даёт немедленный результат и простую обработку ошибок, но создаёт временную связанность: если downstream лежит или тормозит, деградирует и вызывающий. Асинхронный через Kafka развязывает во времени: продюсер не знает о консьюмерах, система переживает недоступность получателя, легко добавлять новых подписчиков, но появляется согласованность в итоге, дубликаты и необходимость идемпотентности, а сквозной сценарий сложнее отлаживать. Практическое правило: синхронно только то, что нужно пользователю прямо сейчас, с обязательным таймаутом и circuit breaker; всё остальное — события. Операции, где пользователь ждёт результат долгой обработки, отдают 202 Accepted с correlationId, а клиент получает результат поллингом, через SSE или webhook. Внутри одного сервиса синхронные вызовы допустимы везде: важна граница процесса. Ещё правило — не смешивать: если API уже вернул 202, внутри того же запроса нельзя делать длинные цепочки синхронных вызовов, иначе мы вернёмся к распределённой транзакции через таймауты. Для аудита, уведомлений, обновления справочников и интеграций с внешними системами асинхронный путь почти всегда выигрывает: он даёт естественный буфер и повторную обработку.', 'Как вы отдаёте клиенту результат асинхронной операции — polling, SSE или webhook, и что выбрали бы для внутреннего банковского UI?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Что такое Saga и в каком случае вы выберете хореографию, а в каком оркестрацию?', 'Saga — это последовательность локальных транзакций, у каждой из которых есть компенсирующее действие; она нужна там, где распределённые транзакции неприменимы (2PC блокирует ресурсы и не работает с Kafka, а JPA и Kafka в одну XA-транзакцию не собрать). Хореография строится на событиях: каждый сервис подписан на события других и сам решает, что делать дальше. Плюсы — слабая связанность, легко добавлять участников, нет единой точки отказа; минусы — сценарий размазан по сервисам, его сложно увидеть целиком, тестировать и дебажить, есть риск циклов событий. Оркестрация вводит отдельный компонент (Camunda или своя state machine), который хранит состояние саги, шлёт команды и запускает компенсации: логика видна целиком, легко тестировать, но появляется центральный компонент, который надо масштабировать и защищать. На практике получается гибрид: оркестратор для сложного многошагового процесса вроде оформления продукта, хореография для простых реакций вроде уведомлений и аудита. Обязательные требования к любой саге: каждый шаг идемпотентен, состояние персистентно и переживает рестарт, «застрявшие» саги видны в мониторинге и имеют ретрай или ручной разбор. И главное отличие от отката: если деньги уже списаны, компенсация — это новый бизнес-шаг (возврат) со своей логикой, учётом и отчётностью, а не магический rollback.', 'Как спроектировать компенсацию для шага, где деньги уже списаны, и чем она принципиально отличается от отката транзакции?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как решить проблему dual write между БД и Kafka? Объясните Outbox и его эксплуатацию.', 'Dual write — это попытка записать в БД и отправить в Kafka в одном методе: если одна операция пройдёт, а вторая нет, получим либо потерю события, либо событие без данных, и никакая транзакция тут не поможет. Transactional Outbox решает это так: в той же локальной транзакции, что и бизнес-данные, пишется строка в таблицу outbox с id, типом, payload, ключом агрегата и статусом. Публикатор — либо планировщик, который читает неотправленные строки и после успешной отправки помечает их, либо CDC (Debezium читает WAL и публикует изменения), что даёт минимальную задержку и не грузит базу опросом. Публикация получается at-least-once, поэтому потребители обязаны быть идемпотентными: таблица processed_messages с первичным ключом по message_id плюс изменение бизнес-данных в одной транзакции. Чистить outbox обязательно — партиционирование по дате или удаление старше N дней, иначе таблица станет источником деградации. Мониторить нужно две метрики: возраст самого старого неотправленного сообщения и долю ошибок публикации; по ним сразу видно, встал ли публикатор. Порядок событий по агрегату обеспечивается ключом партиционирования (aggregateId), иначе потребитель может увидеть update раньше create. Из минусов Outbox — дополнительная таблица, лишняя нагрузка и необходимость следить за слоем публикации; из плюсов — простота объяснения и отсутствие магии с транзакциями Kafka.', 'Чем CDC-подход с Debezium лучше планировщика и какие у него подводные камни в эксплуатации?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Откуда берутся дубликаты в распределённой системе и как вы делаете обработку идемпотентной?', 'Дубликаты неизбежны при доставке at-least-once: retry после таймаута, когда операция на самом деле прошла, повторная обработка после ребалансировки Kafka с незакоммиченным offset, повторная публикация после падения продюсера. Базовая техника — дедупликация по стабильному идентификатору: message_id, который генерирует продюсер, или естественный бизнес-ключ вроде номера платежа. Реализация — таблица processed_messages с первичным ключом по message_id, куда строка вставляется в одной транзакции с изменением бизнес-данных; конфликт первичного ключа означает, что сообщение уже обработано, и мы его пропускаем. Принципиальный момент: проверка «есть ли запись» перед обработкой не защищает от гонки, нужна атомарная вставка или уникальный индекс, иначе два потока обработают одно сообщение параллельно. Для HTTP используется Idempotency-Key с хранением результата в Redis или таблице с TTL, а в БД последним рубежом остаётся unique constraint и обработка DataIntegrityViolationException. Идемпотентный продюсер Kafka защищает от дублей внутри брокера при ретраях, но не от повторной публикации на уровне приложения, поэтому ключ события должен быть осмысленным, а не случайным на каждый retry. Для денежных операций технической дедупликации мало: нужны явные состояния (PENDING, DONE, FAILED) и сверка, потому что отсутствие ответа не означает, что операция не выполнена. Дубликаты стоит измерять метрикой: резкий рост сигнализирует о проблемах с ретраями, ребалансировкой или недоступностью downstream.', 'Как построить дедупликацию, которая работает при одновременной обработке одного сообщения двумя потоками?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как вы строите отказоустойчивые синхронные вызовы: retry, backoff, таймауты и circuit breaker?', 'Retry без backoff превращает деградацию downstream в шторм, поэтому используется экспоненциальная задержка с jitter: база 200 мс, множитель 2, максимум 10-30 секунд и случайный разброс, чтобы клиенты не били синхронно. Ретраить имеет смысл только идемпотентные операции и транзиентные ошибки: таймаут, connect refused, 5xx и 429, но никогда не бизнес-ошибки 4xx. Число попыток небольшое, 2-3: глубже вглубь лучше уходить через Kafka-ретраи, чем ждать в HTTP-потоке. Resilience4j даёт circuit breaker со скользящим окном, порогом ошибок около 50%, медленными вызовами и переходами CLOSED → OPEN → HALF_OPEN; в OPEN вызовы сразу отклоняются, что защищает вызывающего и даёт downstream время восстановиться. Bulkhead ограничивает число одновременных вызовов, RateLimiter — RPS, всё это доступно через аннотации @CircuitBreaker, @Retry, @Bulkhead, но помним про self-invocation: аннотации работают только через прокси. Таймауты обязательны и должны быть меньше таймаута клиента: connect 300-500 мс, read 1-3 секунды, плюс общий бюджет на весь путь запроса, иначе медленный сервис съест пул потоков и потянет за собой остальных. Retry и breaker согласуются так, чтобы retry не прожигал окно breaker''а: обычно retry снаружи, breaker внутри, а параметры подобраны по общему бюджету времени. Fallback должен быть осмысленным — кэш, дефолтное значение или явная деградация, иначе он просто маскирует аварию и мешает алертам.', 'Как согласовать значения retry, timeout и breaker, чтобы при массовом сбое не получить retry storm?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как вы наблюдаете сквозной сценарий в микросервисах и как объясняете бизнесу eventual consistency?', 'Наблюдаемость строится из трёх слоёв: структурированные логи, метрики и распределённые трейсы, связанные одним traceId. В логи пишется JSON с traceId, spanId и request-id, MDC заполняется в фильтре, поэтому всю операцию видно в Loki или Kibana одной выборкой по идентификатору. Трейсинг реализуется Micrometer Tracing с OpenTelemetry или Brave: заголовок W3C traceparent пробрасывается через RestClient и WebClient автоматически, а через Kafka — в заголовках сообщений, и в Grafana Tempo или Jaeger видна цепочка спанов с длительностями, где именно потерялось время. Метрики — Actuator, Micrometer и Prometheus, причём алерты ставятся на RED-метрики (rate, errors, duration) и p95/p99, а не на CPU. Eventual consistency означает окно между «операция принята» и «операция видна во всех представлениях»: это окно нужно измерять (лаг консьюмеров, возраст последнего обработанного события), задавать по нему SLO и объяснять бизнесу через поведение UI, а не через теорию. В интерфейсе правильный ответ — показывать статус «в обработке», а не «данных нет», а для read-your-writes при необходимости читать из основной БД или ждать конкретное событие с таймаутом. Дополнительно нужна сверка (reconciliation), которая периодически добивает расхождения за прошлый период, потому что идеальной гарантии доставки не существует. Ключевое правило: eventual consistency — это не «когда-нибудь», у неё должны быть числовые границы и алерты при их превышении.', 'Какие метрики вы бы повесили, чтобы доказать бизнесу, что данные сходятся за приемлемое время?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как версионировать API и как выкатывать миграции БД без простоя при rolling update?', 'Версионирование: для публичных API проще всего URI-версия /api/v1/... — она видна в логах, трейсах и легко роутится; header-based подход (Accept: application/vnd.bank.v2+json) даёт чище URL, но хуже отлаживается, а версия в query-параметре — антипаттерн. Внутри организации разумно не версионировать каждый чих, а соблюдать обратную совместимость: новые поля добавлять, а удалять и менять смысл только через новую версию с периодом устаревания (Sunset-заголовок, метрики вызовов старой версии, чтобы понимать, кто ей ещё пользуется). Контракт описывается в OpenAPI до кода, а в CI ставится проверка на breaking changes, чтобы клиенты не узнавали об изменениях в проде. Миграции без простоя делаются по паттерну expand/contract: сначала добавляем nullable-колонку или новую таблицу, затем код пишет и читает с фолбэком, потом батчами бэкфиллим данные с паузами, затем переключаем чтение и только в следующем релизе удаляем старое. Блокирующих операций избегаем: в PostgreSQL ADD COLUMN с DEFAULT не переписывает таблицу только с 11-й версии, индексы создаются CONCURRENTLY, а переименование колонок делается через фазу, когда обе версии кода работают с обоими именами. Миграции Flyway или Liquibase накатываются отдельным шагом до старта новой версии приложения, лежат в git и идемпотентны, а откат — это forward-миграция, а не откат скрипта. При rolling update в Kubernetes старые и новые поды живут одновременно, поэтому схема обязана поддерживать обе версии кода: каждый релиз совместим с предыдущим.', 'Как безопасно переименовать колонку в PostgreSQL при rolling update и почему переименование без переходного периода ломает прод?' from categories where slug = 'microservices';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Какие гарантии доставки даёт Kafka и что нужно настроить, чтобы не терять сообщения?', 'На стороне продюсера acks определяет надёжность: acks=0 не ждёт подтверждения и легко теряет данные, acks=1 ждёт записи на лидере и теряет при падении лидера до репликации, acks=all ждёт подтверждения от всех ISR. Для надёжной записи acks=all работает в связке с replication.factor=3 и min.insync.replicas=2, иначе гарантия фиктивна. enable.idempotence=true добавляет producer id и sequence number, брокер отбрасывает дубликаты при ретраях, а max.in.flight.requests.per.connection до 5 сохраняет порядок, и в Spring Boot это прописывается в spring.kafka.producer.properties. На стороне консьюмера дефолт — at-least-once: обработали, затем коммитим offset; вариант at-most-once (коммит до обработки) теряет сообщения при падении, а exactly-once требует транзакций. Брокер дополнительно защищается min.insync.replicas и unclean.leader.election.enable=false, иначе можно выбрать отставшую реплику лидером и потерять данные. Для критичных событий вроде платежей собирается комбинация: acks=all, три реплики, идемпотентный продюсер и идемпотентный консьюмер. Стоит сразу признать, что сквозного exactly-once между Kafka и БД нет, поэтому мы получаем effectively-once за счёт дедупликации на приёмнике. Проверяется это интеграционным тестом, в котором убивают брокера или консьюмера и смотрят, что ни одно событие не потеряно.', 'Что произойдёт, если min.insync.replicas=1 при acks=all и упадёт лидер с несинхронизированной репликой?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как ключ партиционирования влияет на порядок сообщений и на баланс нагрузки?', 'Kafka гарантирует порядок только внутри партиции, поэтому все события одного агрегата должны попадать в одну партицию — этого добиваются ключом записи, например aggregateId или accountId, и тогда update не обгонит create. Если ключ не задан, включается sticky partitioning: продюсер наполняет батч в одну партицию, затем переключается на другую, и порядок между событиями одного агрегата не гарантирован. Баланс страдает при плохом ключе: ключ с малым числом значений, перекос вроде одного огромного клиента или общий ключ на весь топик дают горячую партицию, которая отстаёт первой. Лечится составным ключом (accountId плюс bucket) или сознательным изменением схемы ключей с пониманием, что порядок при этом рвётся. Число партиций задаёт максимальный параллелизм консьюмеров в группе: консьюмеров больше, чем партиций, и лишние простаивают; увеличить число партиций можно, но при хешировании по ключу меняется маппинг и порядок между старыми и новыми сообщениями уже не гарантирован. Прикидываем целевой throughput: при 5 RPS тридцать партиций избыточны, каждая партиция — это файлы, память и время ребалансировки. Для retry-топиков и DLQ ключ нужно сохранять, иначе повторные попытки пойдут в другие партиции и порядок обработки изменится.', 'Что делать, если горячий ключ обязателен (один крупный клиент), а баланс всё равно нужен?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как работают consumer groups, ребалансировка и выбор между auto и manual commit offset?', 'Consumer group — единица масштабирования: партиции топика распределяются между членами группы, каждая партиция читается ровно одним консьюмером группы, а разные группы читают топик независимо со своими offset''ами в служебном топике __consumer_offsets. enable.auto.commit=true по умолчанию коммитит последний отданный консьюмеру offset раз в 5 секунд, а не фактически обработанный, поэтому при падении часть сообщений может потеряться. Для надёжности ставят false и коммитят после успешной обработки: ack.acknowledge() в Spring Kafka с AckMode MANUAL_IMMEDIATE или ручной commitSync/commitAsync, причём для «ровно один раз на партицию» коммит делают по партициям. Ребалансировка запускается при подключении или отвале консьюмера, изменении числа партиций и при превышении max.poll.interval.ms; eager-протокол отзывает все партиции сразу, cooperative sticky перераспределяет их по одной, что заметно сокращает паузы и является дефолтом в новых версиях. При отзыве партиции нужно через ConsumerRebalanceListener успеть обработать и закоммитить состояние, иначе получим дубликаты при следующем распределении. Отсюда практические настройки: max.poll.records подбирается так, чтобы обработка батча гарантированно укладывалась в max.poll.interval.ms, иначе консьюмер уходит из группы и начинается бесконечный цикл ребалансировок. При 5 RPS достаточно одного консьюмера на несколько партиций, а масштабировать группу нужно до числа партиций и не раньше появления реальной нагрузки.', 'Почему при eager-ребалансировке появляются дубликаты и как cooperative sticky их уменьшает?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Реален ли exactly-once в Kafka и что даёт транзакционный продюсер?', 'Внутри Kafka exactly-once достижим комбинацией идемпотентного продюсера и транзакций: задаётся transactional.id, вызываются initTransactions, beginTransaction, затем чтение, запись и sendOffsetsToTransaction, а завершается всё commitTransaction или abortTransaction. Это даёт атомарную запись в несколько топиков и партиций и атомарный коммит offset''ов вместе с результатом — классический паттерн read-process-write. Консьюмеры с isolation.level=read_committed видят только закоммиченные сообщения, а незавершённая транзакция для них невидима. Цена: транзакции требуют acks=all, включённой идемпотентности и дополнительных RPC, поэтому throughput падает, а эксплуатация усложняется. В Spring это KafkaTransactionManager или ChainedKafkaTransactionManager вместе с @Transactional на методе с @KafkaListener, причём важно не перепутать порядок транзакционных менеджеров. Сквозной exactly-once между Kafka и реляционной БД недостижим: XA с Kafka нормально не работает, поэтому либо outbox с идемпотентным консьюмером, либо Kafka Streams с локальным состоянием. На наших 5 RPS я выбрал бы outbox плюс идемпотентность: проще в эксплуатации, отладке и объяснении, а транзакционный продюсер дал бы несоразмерную сложность без практического выигрыша. Транзакционный продюсер оправдан там, где реально нужен потоковый EOS, например в обработке потоковых агрегатов со строгой семантикой.', 'Какие настройки обязательны для транзакционного продюсера и что увидит консьюмер, если забыть про isolation.level=read_committed?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как настроить retention и защититься от отставания консьюмеров (backpressure)?', 'Retention задаётся либо по времени (retention.ms, по умолчанию 7 дней), либо по размеру (retention.bytes), а cleanup.policy=compact применяется для компактификации по ключу, когда нужно хранить только последнее состояние (компакт-топики с tombstone как null value для удаления). Выбор ретеншна определяет, насколько можно отстать и насколько глубоко перечитать историю, поэтому для команд и состояний нужен compact, а для событий — временное окно, согласованное с возможностями восстановления. Backpressure в Kafka — это набор приёмов, чтобы не уронить консьюмер: max.poll.records ограничивает размер батча, max.partition.fetch.bytes и fetch.min.bytes регулируют объём, а pause() и resume() (или pause/resume на KafkaListenerEndpointRegistry в Spring) позволяют прекратить чтение, когда downstream медленный. Если обработка блокирующая, её выносят в отдельный пул или увеличивают concurrency, а ручной ack позволяет контролировать момент коммита. Иначе истекает max.poll.interval.ms, консьюмер выпадает из группы, начинается ребалансировка, и та же пачка приходит повторно — то есть backpressure превращается в проблему дубликатов. При росте лага отставание лечится увеличением числа консьюмеров до числа партиций, оптимизацией обработчика и throttling, а не бесконечным увеличением max.poll.records. Дополнительно помогает сжатие lz4 или zstd, а крупные payload лучше хранить в S3 и передавать ссылку.', 'Как pause/resume реализуется в Spring Kafka и когда он предпочтительнее обычных ретраев?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'SENIOR', 'Как вы организуете DLQ и ретраи и как мониторите лаг потребителей?', 'Стратегия ошибок должна быть явной: транзиентные сбои (таймаут внешнего API, дедлок БД) ретраятся, нетранзиентные (невалидный payload, бизнес-ошибка) уходят в DLT сразу, иначе ретраи будут вечно блокировать партицию и лаг будет расти. В Spring Kafka используется DefaultErrorHandler с FixedBackOff или ExponentialBackOff и обязательным ограничением попыток (3-10), а @RetryableTopic сам создаёт retry-топики с задержкой и deadLetterTopic, не блокируя основной поток. При публикации в DLQ сохраняются заголовки с исходным топиком, партицией, offset, исключением и стектрейсом, а ключ сообщения остаётся тем же, чтобы реплей попал в правильную партицию. DLT не должна быть кладбищем: на неё нужен алерт, регулярный разбор, реплей после фикса и учёт уже обработанных сообщений при повторной публикации. Мониторинг лага делается через kafka-consumer-groups.sh --describe (CURRENT-OFFSET против LOG-END-OFFSET) и экспортируется в Prometheus метриками Micrometer (kafka.consumer.fetch.manager.records.lag.max) или через Kafka Exporter и Burrow. Алертить нужно не только на абсолютный лаг, но и на возраст последнего обработанного сообщения: если поток вообще встал, лаг может быть нулевым на пустом топике, а проблема останется незамеченной. Ещё полезно наблюдать счётчик ребалансировок: его рост почти всегда означает, что обработка не укладывается в max.poll.interval.ms.', 'Как построить инструмент реплея из DLT, чтобы не создать дубликаты уже успешно обработанных сообщений?' from categories where slug = 'kafka';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Какие индексы есть в PostgreSQL, что такое составной и покрывающий индекс и в каких случаях планировщик индекс не использует?', 'B-tree — дефолтный индекс, поддерживает =, <, <=, >, BETWEEN, IN, IS NULL и LIKE ''abc%'' (префиксный поиск). Составной индекс работает по правилу левого префикса: индекс (user_id, created_at) ускорит WHERE user_id = ? и WHERE user_id = ? AND created_at >= ?, но не WHERE created_at >= ? — поэтому колонки равенства ставят первыми, а диапазон последним. Покрывающий индекс делаю через INCLUDE, например CREATE INDEX idx_orders_user_created ON orders(user_id, created_at DESC) INCLUDE (status, amount) — тогда возможен Index Only Scan без обращения к heap, но он работает только когда visibility map свежая, то есть autovacuum успевает отметить страницы. Планировщик не берёт индекс, если на колонке функция или приведение типа (WHERE lower(email) = ?, или bigint-колонка сравнивается со строкой — неявный cast ломает индекс), при wildcard в начале (LIKE ''%abc''), при низкой селективности (индекс по boolean, фильтр на 60% таблицы — Seq Scan честно дешевле), на маленьких таблицах, при устаревшей статистике и в условиях ≠ / NOT IN по большой части данных. Проверяю всегда фактическим планом EXPLAIN (ANALYZE, BUFFERS) — если вижу Seq Scan с Filter и большим actual rows, разбираюсь, какой именно предикат мешает. Пример исправления: CREATE INDEX CONCURRENTLY idx_users_email_lower ON users (lower(email)); — CONCURRENTLY не блокирует запись, но не может выполняться внутри транзакции. У меня таблицы порядка 1 млн строк и нагрузка до 5 RPS, там индексы обычно берутся, но при селективности выше ~10% планировщик справедливо выбирает Seq Scan, и это не проблема.', 'Что делать, если индекс есть, но в плане всё равно Seq Scan? Что такое неявное приведение типов и как оно влияет на использование индекса?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Расскажите про частичные (partial) индексы: когда они дают выигрыш и какие у них ограничения?', 'Частичный индекс создаётся с предикатом WHERE и индексирует только подмножество строк, например CREATE INDEX idx_orders_active ON orders(created_at) WHERE status = ''ACTIVE''. Если активных заказов 3% из миллиона строк, индекс получается в десятки раз меньше и дешевле в обслуживании при записи, что напрямую влияет на скорость вставок и на объём bloat. Второй частый кейс — уникальность при soft delete: CREATE UNIQUE INDEX uq_users_email_active ON users(email) WHERE deleted_at IS NULL, тогда можно многократно «удалять» пользователя, не теряя уникальность email среди живых записей. Третий кейс — очереди и outbox: CREATE INDEX idx_outbox_pending ON outbox(created_at) WHERE processed = false, чтобы индекс не разрастался вместе с обработанными строками. Главное ограничение: индекс применяется, только если планировщик может доказать, что предикат запроса логически подразумевает предикат индекса; запрос с параметром WHERE status = $1 им пользоваться не будет, поэтому такие индексы пишут под конкретный запрос или набор статусов. Ещё нюанс — условие должно быть иммутабельным (не now() напрямую), иначе создание упадёт. В итоге partial index — это не замена обычному, а точечная оптимизация под конкретный горячий запрос; я всегда проверяю применение через EXPLAIN (ANALYZE) уже после создания.', 'Будет ли использован частичный индекс при запросе с параметром status = $1? Как вы проверяете, что он реально применяется?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы читаете EXPLAIN (ANALYZE, BUFFERS) и как находите медленные запросы в продакшене?', 'EXPLAIN показывает план и оценки cost/rows без выполнения, а EXPLAIN (ANALYZE, BUFFERS) реально выполняет запрос и даёт фактические строки по узлам, время и работу с буферами (shared hit/read). Читаю план снизу вверх и первым делом смотрю расхождение estimated rows и actual rows больше чем в 10 раз — это признак устаревшей статистики, лечится ANALYZE table и повышением default_statistics_target для проблемной колонки. Затем узлы: Seq Scan с Filter на большой таблице — нет подходящего индекса; Nested Loop, где справа миллион строк, — плохая оценка или отсутствующий индекс на join-колонке; Sort с external merge Disk — не хватает work_mem (ставлю локально SET LOCAL work_mem = ''64MB'', а не глобально); Rows Removed by Filter в большом количестве — индекс не селективен. BUFFERS показывают, в кэш ли мы попадаем: если shared read большой, а hit маленький — working set больше shared_buffers. Методология поиска: включаю pg_stat_statements (CREATE EXTENSION pg_stat_statements) и сортирую топ по total_exec_time, а не по mean, потому что одна тяжёлая частотная операция важнее экзотики; для разового разбора включаю log_min_duration_statement = 1000 или auto_explain с auto_explain.log_analyze = on для планов медленных запросов. Реальный пример: запрос на пару секунд по таблице ~1 млн строк сравнивал bigint-колонку со строковым значением, приходил Seq Scan и перечитывание всего; после приведения типа в запросе и индекса время ушло в десятки миллисекунд.', 'Как найти тяжёлые запросы, если pg_stat_statements нет? Что делать, если динамический фильтр с OR по нескольким колонкам?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как устроен MVCC в PostgreSQL, зачем нужен vacuum и как вы контролируете bloat и wraparound?', 'MVCC реализован через версии строк: у каждой строки есть xmin/xmax, UPDATE не перезаписывает строку, а создаёт новую версию, а старая остаётся видимой для транзакций со старым снапшотом. Читатели не блокируют писателей и наоборот — это главный плюс, но цена — мёртвые версии, которые занимают страницы и создают bloat. VACUUM помечает мёртвые кортежи как переиспользуемые, autovacuum запускается по формуле autovacuum_vacuum_threshold (50) + autovacuum_vacuum_scale_factor (0.2) от размера таблицы; для миллионных «горячих» таблиц это значит, что вакуум приходит поздно, поэтому я задаю per-table настройки: ALTER TABLE orders SET (autovacuum_vacuum_scale_factor = 0.02, autovacuum_vacuum_cost_limit = 1000). VACUUM FULL переписывает таблицу под ACCESS EXCLUSIVE и в продакшене не применяется — вместо него pg_repack или работа через партиции (DETACH/DROP вместо массового DELETE). Долгие и, что чаще, «idle in transaction» транзакции держат горизонт и не дают вакууму удалять версии, поэтому у нас стоит idle_in_transaction_session_timeout = 30s и statement_timeout. Контроль: SELECT relname, n_dead_tup, n_live_tup, last_autovacuum FROM pg_stat_user_tables ORDER BY n_dead_tup DESC, плюс pg_stat_progress_vacuum для текущего прогресса. Отдельно слежу за wraparound: счётчик транзакций 32-битный, и при недостижении порога заморозки (autovacuum_freeze_max_age, default 200 млн) база уйдёт в read-only — смотрю age(datfrozenxid) в pg_database и алертю задолго до 1.5 млрд.', 'Почему VACUUM FULL опасен под нагрузкой? Как понять, что таблица раздута и насколько?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Какие уровни изоляции есть в PostgreSQL, какие аномалии они допускают и как вы защищаетесь от lost update?', 'В PostgreSQL четыре уровня: Read Committed (по умолчанию), Repeatable Read и Serializable, а Read Uncommitted работает как Read Committed, потому что грязное чтение невозможно в принципе. На Read Committed каждый оператор видит снапшот на начало оператора, поэтому два SELECT внутри одной транзакции могут вернуть разные данные — non-repeatable read. Repeatable Read берёт снапшот на начало транзакции, фантомы в PostgreSQL не появляются, но при попытке изменить строку, которую параллельно изменила другая транзакция, получаем serialization failure с SQLSTATE 40001, и транзакцию нужно повторять с идемпотентной логикой. Serializable добавляет SSI и predicate-блокировки, ловит write skew, но тоже может отдавать 40001 — у нас это закрывается retry-механизмом (@Retryable в Spring или spring-retry с backoff). Типичная аномалия, которую я видел: приложение читает баланс, считает в Java и пишет UPDATE ... SET balance = 100 — обновление теряется; лечится либо атомарным UPDATE balance = balance - ? (PostgreSQL перечитает строку под блокировкой), либо SELECT ... FOR UPDATE, либо оптимистичной блокировкой через @Version в JPA. На практике 95% операций у нас Read Committed, Repeatable Read — только для отчётов, где нужен консистентный снапшот по нескольким таблицам, Serializable — точечно для денежных инвариантов. Чем выше уровень, тем больше 40001 и важнее retry, поэтому повышение уровня всегда сопровождается изменением обработки ошибок.', 'Что такое write skew и почему его ловит только Serializable? Как реализовать ретрай 40001 в Spring-сервисе?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Какие блокировки бывают в PostgreSQL, как возникает deadlock и как вы его находите и предотвращаете?', 'На уровне строк есть FOR UPDATE, FOR NO KEY UPDATE, FOR SHARE и FOR KEY SHARE, на уровне таблиц — ACCESS EXCLUSIVE (ALTER TABLE, TRUNCATE, LOCK TABLE), и короткие DDL всё равно берут ACCESS EXCLUSIVE, поэтому миграции мы делаем с lock_timeout = ''3s'' и повтором, чтобы не собрать очередь из ожидающих запросов. Deadlock возникает, когда две транзакции берут строки в разном порядке; PostgreSQL находит цикл через deadlock_timeout (по умолчанию 1 с) и убивает одну из транзакций ошибкой 40P01, которую приложение обязано ретраить. Профилактика: всегда захватывать строки в одном порядке (SELECT ... FROM accounts WHERE id IN (...) ORDER BY id FOR UPDATE), не держать транзакцию открытой во время вызовов внешних сервисов и пользовательского ввода, для очередей использовать SELECT ... FOR UPDATE SKIP LOCKED. Диагностика: SELECT pid, pg_blocking_pids(pid), wait_event FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid)) > 0, при необходимости join pg_locks и pg_stat_activity, чтобы увидеть, кто кого держит; включаю log_lock_waits = on, чтобы в логе видеть ожидания дольше секунды. Ещё один частый источник — неявная блокировка лишних строк: UPDATE по колонке без индекса из-за Seq Scan блокирует гораздо больше строк, чем предполагается по условию. Отдельно держу в голове, что блокировки удерживаются до конца транзакции, поэтому разбиваю длинные batch-операции на короткие коммиты.', 'Как найти виновника блокировки, если в pg_stat_activity видно только Lock:transactionid? Что делать с долгими batch-операциями, чтобы они не блокировали?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Когда нужно партиционирование, как оно делается и какие у него подводные камни?', 'Declarative partitioning появился в PostgreSQL 10: RANGE по дате, LIST по статусу или региону, HASH для равномерного распределения; объявляется CREATE TABLE events (...) PARTITION BY RANGE (created_at), затем CREATE TABLE events_2026_01 PARTITION OF events FOR VALUES FROM (''2026-01-01'') TO (''2026-02-01''). Главный выигрыш — partition pruning: запрос с предикатом по ключу партиционирования читает одну партицию, и в EXPLAIN видно, сколько партиций реально просканировано. Плюс дешёвая архивация: ALTER TABLE events DETACH PARTITION events_2025_01 вместо DELETE по миллионам строк — нет bloat и нет долгой транзакции. Плюс вакуум работает по кускам, и это стабильнее, чем один огромный файл. Подводные камни: уникальность действует только в пределах партиции, поэтому ключ партиционирования приходится включать в первичный ключ и в unique-индексы; десятки партиций нормально, тысячи — уже ухудшают планирование и время планирования запроса; запрос без ключа партиционирования сканирует всё. Партиции создаю заранее job-ом в Jenkins (или pg_partman), держу DEFAULT-партицию как страховку от ошибки вставки вне диапазона. При честных объёмах ~1 млн строк на таблицу партиционирование не обязательно, я применял его там, где таблица растёт сотнями тысяч строк в месяц и нужен быстрый purge по ретенции.', 'Как выглядит безопасный переход с обычной таблицы на партиционированную без остановки сервиса? Что произойдёт с вставкой вне диапазона партиций?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как настроить HikariCP и как понять, что проблемы из-за пула соединений, а не из-за базы?', 'HikariCP — пул по умолчанию в Spring Boot, ключевые параметры: maximumPoolSize, minimumIdle, connectionTimeout, idleTimeout, maxLifetime, keepaliveTime, validationTimeout и leakDetectionThreshold. maximumPoolSize я считаю по реальному параллелизму запросов и числу ядер, а не «побольше»: при 5 RPS и десятке сервисов нам хватало 10–20 соединений на инстанс, и увеличение пула свыше числа ядер ускорения не даёт, зато увеличивает конкуренцию в PostgreSQL за max_connections. maxLifetime обязательно меньше idle-таймаута на стороне БД и балансировщика (я ставил 25–30 минут при 30 минутах в Postgres и pgBouncer), иначе приложение начнёт получать «connection closed» после закрытия соединений на сервере. connectionTimeout держу 3–5 секунд: при исчерпании пула быстро падаем с понятной ошибкой, а не висим. Диагностика — метрики HikariCP через Micrometer: hikaricp_connections_active, _pending, _timeout, _acquire_seconds; если растёт pending, а время acquire большое, дело в пуле или в долгих транзакциях, а не в скорости SQL. Дополнительно я всегда смотрю длительность транзакций и N+1 в JPA, потому что «пул исчерпан» — обычно симптом, а не причина. На dev/stage включаю leakDetectionThreshold = 20s, чтобы видеть незакрытые соединения, а тест-квери для PostgreSQL не нужен — работает JDBC4 isValid().', 'Как считать размер пула, если сервис масштабируется до 10 под? Почему poolSize больше числа ядер не помогает?' from categories where slug = 'postgresql';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Встраивание или ссылки: как вы проектируете модель документа в MongoDB?', 'Правило простое: встраиваю (embed) данные, которые читаются вместе и растут ограниченно — например, массив позиций внутри документа заказа; ссылаюсь — на сущности с независимым жизненным циклом и неограниченным размером (пользователь, справочник товаров). Ключевое ограничение — 16 МБ на документ, и главная ловушка — unbounded array, который растёт неограниченно (события, логи): его выносят в отдельную коллекцию или применяют bucket-паттерн. Встраивание даёт атомарность в пределах одного документа и один round-trip, но дублирование: если название товара изменилось, нужно обновить копии во всех заказах. Ссылки нормализуют данные, но требуют второго запроса или $lookup, а $lookup на больших коллекциях дорогой, поэтому для горячих read-путей я лучше денормализую «исторические» поля (название и цена на момент заказа) и храню их копией как снимок. У нас заказ — это документ с встроенным массивом позиций и копией названий/цен, а справочник товаров — отдельная коллекция, изменения в которую приходят событиями Kafka и подтягиваются идемпотентно. Если данные откровенно реляционные и нужны сложные join с транзакционной консистентностью, я честно говорю, что эту часть лучше держать в PostgreSQL, а не вытягивать в Mongo.', 'Как поддерживать актуальность денормализованных копий? Что делать, когда массив всё-таки растёт неограниченно?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы строите индексы в MongoDB и как читаете explain?', 'Индексы в MongoDB — B-tree, и для составного индекса работает правило ESR: Equality, Sort, Range — сначала поля равенства, потом сортировка, затем диапазон. Пример: db.orders.createIndex({userId: 1, status: 1, createdAt: -1}) покрывает фильтр по userId и status и сортировку по createdAt. Проверяю фактическим explain: db.orders.find({userId: 42}).sort({createdAt: -1}).explain(''executionStats''), где winningPlan указывает COLLSCAN или IXSCAN, totalKeysExamined и nReturned показывают селективность, а totalDocsExamined = 0 означает, что запрос покрыт индексом и в документы мы не ходили. Индекс не используется при несовпадении типов (userId: ''42'' против числа), при неякорном regex, при $ne и $nin, а сортировка по неиндексированному полю даёт blocking SORT с лимитом 32 МБ памяти. TTL-индексы решают задачу авто-очистки: db.sessions.createIndex({createdAt: 1}, {expireAfterSeconds: 3600}) — у нас это заменяло cron-джобу. Индексы — это компромисс: каждый дополнительный индекс замедляет запись и занимает память, поэтому я сначала смотрю реальный профиль нагрузки (keysExamined/docsExamined), а не создаю индекс «на всякий случай». Для горячих read-путей проекция должна содержать только поля индекса — это самый дешёвый вариант чтения.', 'Что такое правило ESR на конкретном примере? Как проверить, что индекс не вредит записи?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как устроен aggregation pipeline и как избежать типичных проблем производительности в нём?', 'Пайплайн — это последовательность стадий, где документ проходит через $match, $project, $group, $sort, $lookup, $unwind, $facet, и порядок стадий напрямую определяет стоимость. Правила, которых я держусь: $match как можно раньше и по индексированным полям, $project сразу после, чтобы уменьшить размер документа до тяжёлых стадий, $limit перед $skip там, где это возможно. Пример: db.orders.aggregate([{$match: {status: ''PAID'', createdAt: {$gte: ISODate(''2026-01-01'')}}}, {$group: {_id: ''$customerId'', total: {$sum: ''$amount''}, cnt: {$sum: 1}}}, {$sort: {total: -1}}, {$limit: 20}]) — и ключевой момент, что первый $match должен опираться на составной индекс, иначе это COLLSCAN по всей коллекции. $lookup — левый join, на больших объёмах он дорогой, и я предпочитаю заранее подготовленные materialized-коллекции или вынос аналитики в PostgreSQL/ClickHouse, если отчёты тяжёлые. allowDiskUse: true спасает от ошибки превышения лимита памяти на стадии, но это скорее индикатор, что пайплайн надо переписать. Пагинация через $skip/$limit читает и выбрасывает документы, поэтому на глубоких страницах применяю keyset-пагинацию по _id или createdAt. Для отладки смотрю explain по пайплайну и $indexStats, чтобы понять, какой индекс реально работает под нагрузкой.', 'Как построить пагинацию без $skip на 50-й странице? Когда $lookup всё же оправдан?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Когда в MongoDB можно и нельзя использовать транзакции и как базово работает шардирование?', 'Multi-document транзакции работают на реплика-сете с версии 4.0 и на шардированном кластере с 4.2, синтаксис через сессию: const s = client.startSession(); s.withTransaction(async () => {...}). Ограничения существенные: transactionLifetimeLimitSeconds по умолчанию 60 секунд, есть лимиты на размер записей в oplog, а долгие транзакции создают конкуренцию за документы и рост версий, поэтому я проектирую модель так, чтобы критичное изменение помещалось в один документ — это атомарно, быстро и не требует транзакции. Транзакцию беру там, где реально нужно консистентно записать в две-три коллекции (например, изменить баланс счёта и добавить запись операции), обязательно с обработкой TransientTransactionError и идемпотентностью операции. Транзакции не стоит использовать как способ «всё делать как в SQL»: на большом трафике это узкое место, и часто проще event sourcing или outbox-паттерн. Шардирование: shard key определяет распределение данных, и хороший ключ имеет высокую кардинальность, не монотонно растёт и поддерживает основные запросы, иначе запрос становится scatter-gather по всем шардам. Монотонный ключ (_id, timestamp) даёт hot shard — вся запись в один шард, поэтому применяют hashed keys: sh.shardCollection(''db.orders'', {customerId: ''hashed''}) или составной ключ {customerId: 1, createdAt: 1}. Плюс есть zones/tags для географического размещения и balancer для перераспределения чанков. Честно: полноценный шардированный кластер я в продакшене не эксплуатировал — знаю теорию и базовую настройку, пробовал в тестовом окружении; в проде у нас были реплика-сеты.', 'Как выбрать shard key для коллекции заказов? Что делать, если ключ уже выбран неудачно?' from categories where slug = 'mongodb';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Какие структуры данных есть в Redis, как устроен TTL и какие eviction-политики вы выставляете?', 'Строки (SET/GET, INCR) — счётчики и лимиты, хэши (HSET/HGETALL) — объекты с экономией памяти на множестве полей, списки (LPUSH/BRPOP) — простые очереди, множества и sorted sets (SADD/ZADD, ZREMRANGEBYSCORE) — уникальность, лидерборды, rate limiting, плюс Bitmap, HyperLogLog для приблизительного подсчёта уникальных значений и Streams (XADD/XREADGROUP) как лёгкая альтернатива Kafka для мелких задач. TTL ставится на ключ: SET key value EX 3600, EXPIRE, PEXPIRE — важно помнить, что TTL действует на ключ, а не на отдельное поле хэша, поэтому сущности с разным временем жизни нужно разносить по ключам. Eviction задаётся maxmemory-policy: allkeys-lru/lfu, volatile-lru/lfu/ttl/random, noeviction (при заполнении запись падает с ошибкой). Для чистого кэша беру allkeys-lfu или allkeys-lru, для данных, которые обязаны сохраниться, — noeviction и алерт по памяти. maxmemory выставляю меньше лимита контейнера (например 1.5 ГБ при лимите 2 ГБ), чтобы Redis не был убит по OOM, и слежу за INFO memory (used_memory, fragmentation_ratio) и INFO stats (evicted_keys, hits/misses), ставя алерт на evicted_keys > 0 и hit rate ниже 90%. Redis однопоточный по командам, поэтому KEYS *, большие SMEMBERS или DEL миллиона ключей блокируют всё — использую SCAN и UNLINK вместо KEYS и DEL.', 'Какую политику вы бы взяли для сессий и почему? Что произойдёт при noeviction и заполненной памяти?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы организуете кэширование (cache-aside), инвалидацию и защиту от cache stampede?', 'Основной паттерн у нас cache-aside: приложение читает ключ, при промахе идёт в БД и кладёт значение с TTL (SET key value EX 300), при изменении данных ключ инвалидируется командой DEL. Инвалидацию делаю строго после успешного коммита транзакции — через @TransactionalEventListener(phase = AFTER_COMMIT) или после commit в явном виде, иначе параллельный читатель закэширует старое значение из ещё не закоммиченного состояния, и это классическая ошибка, которую потом очень трудно поймать. TTL ставлю всегда, даже когда есть явная инвалидация, — он страховка от пропущенной инвалидации, а ещё защита от того, что схема кэша меняется. Cache stampede (другое название thundering herd): популярный ключ истёк, и сотни запросов одновременно идут в БД — варианты лечения: распределённый лок на пересчёт (SET key:lock 1 NX PX 5000), single-flight через Caffeine с блокировкой по ключу, «логический TTL» с фоновым обновлением, refresh-ahead. Ещё паттерны: write-through (пишем и в кэш, и в БД синхронно) и write-behind (риск потери данных при падении Redis, поэтому для денежных данных не использую). Cache penetration от запросов за заведомо несуществующими ключами закрываю кэшированием пустого результата с коротким TTL или Bloom-фильтром. При нашей нагрузке до 5 RPS stampede был не критичен, но лок на пересчёт справочников я реализовывал — он снимал пики на старте деплоя, когда кэш пустой.', 'Что делать с холодным кэшем после деплоя? Как инвалидировать ключ, который зависит от нескольких сущностей?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как правильно сделать distributed lock в Redis и в чём критика Redlock?', 'Базовая корректная реализация — одна атомарная команда SET lock_key <uuid> NX PX 30000: NX гарантирует, что лок ставит только первый, PX задаёт TTL, а уникальный токен нужен, чтобы снять именно свой лок. Снятие делаю атомарно Lua-скриптом: if redis.call(''get'', KEYS[1]) == ARGV[1] then return redis.call(''del'', KEYS[1]) else return 0 end (в Java — DefaultRedisScript), потому что GET + DEL по отдельности — окно для гонки. TTL обязателен, иначе падение процесса оставит лок навсегда, но TTL создаёт риск, что работа длится дольше лока и другой узел возьмёт его — поэтому при длительных операциях нужно продление (Redisson делает это watchdog-ом с lockWatchdogTimeout по умолчанию 30 с) либо идемпотентность операции. Redlock — алгоритм на N независимых мастерах, где лок считается взятым при большинстве успешных SET NX — критикуется Мартином Клеппманном в статье How to do distributed locking: из-за clock drift и длинных GC-пауз два процесса могут одновременно решить, что держат лок, поэтому строгих гарантий он не даёт, даже если авторы Redis с этим спорят. Для по-настоящему критичных инвариантов нужны fencing tokens (монотонный номер, по которому хранилище отбрасывает устаревшие записи) или системы координации типа ZooKeeper/etcd, а чаще всего — уникальные индексы и блокировки в самой БД. Практический вывод: Redis-лок годится для «не делать одну и ту же работу дважды» (пересчёт кэша, дедупликация задач), но не для денежных операций. Плюс отдельная тема — hot keys: один популярный ключ бьёт в один шард и в один поток Redis, поэтому его дробят (постфиксиксы с локальными кэшами) или реплицируют чтение на реплики.', 'Что такое fencing token и зачем он нужен? Чем опасен DEL без проверки токена?' from categories where slug = 'redis';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Liquibase или Flyway: что выберете и как организуете changesets?', 'Flyway проще: SQL-файлы вида V1__init.sql, таблица flyway_schema_history и checksum содержимого; Liquibase описывает изменения как changesets формально (id + author + filepath) и держит DATABASECHANGELOG и DATABASECHANGELOGLOCK, поддерживает rollback, контексты, preconditions и абстракции над разными СУБД. Я выбираю так: одна СУБД и команда пишет SQL — Flyway, меньше магии и меньше неожиданностей; несколько СУБД, нужна генерация changelog из JPA-моделей или формальный rollback — Liquibase. В Альфа-Банке у нас был Liquibase: каждый changeset в отдельном файле с обязательными id и author, и правило — не редактировать changeset после попадания в master, иначе checksum mismatch и миграция не применяется. Откат мы делали не rollback-ом, а forward-fix отдельным changeset, потому что откат схемы на уже работающих данных почти всегда опаснее, чем ещё одна миграция вперёд. В CI обязательный шаг validate (liquibase validate или flyway validate) и запрет merge при расхождении, плюс DDL-ревью вторым разработчиком. Миграции прогоняем на пустой БД и на копии прода, чтобы ручные правки в боевой схеме всплыли до релиза, а не после. Отдельный принцип: у приложения нет DDL-прав в рантайме, схему меняет отдельный пользователь в рамках деплоя.', 'Что делать при checksum mismatch в проде? Почему forward-fix, а не rollback?' from categories where slug = 'db-migrations';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как делать миграции обратно совместимыми и обеспечить zero-downtime при rolling update?', 'Базовый принцип — во время деплоя одновременно живут старая и новая версии приложения (у нас 4 пода и rolling update), поэтому схема должна быть совместима с обеими, и любую ломку делаем в три шага expand → migrate → contract. Сначала добавляю новое: колонку nullable или с DEFAULT, индекс через CREATE INDEX CONCURRENTLY (он не блокирует запись, но не может идти внутри транзакции, а при сбое остаётся INVALID-индекс, который надо удалить и пересоздать). Деплою код, который пишет и в старое, и в новое поле, затем бэкфиллю данные батчами (UPDATE ... WHERE id > ? LIMIT 10000 в цикле), чтобы не держать длинную транзакцию и не раздувать WAL, затем код начинает читать только новое, и лишь потом удаляю старое. NOT NULL не ставлю напрямую — сначала ALTER TABLE ... ADD CONSTRAINT ... CHECK (status IS NOT NULL) NOT VALID, потом VALIDATE CONSTRAINT, который берёт только ShareUpdateExclusiveLock и не блокирует запись, в отличие от полного скана под ACCESS EXCLUSIVE. Переименование колонок не использую вообще: делаю новую колонку, бэкфилл и удаление старой, потому что rolling update не переживёт rename. Порядок деплоя фиксирован: сначала совместимые миграции схемы, затем приложение; откат приложения всегда возможен, потому что схема обратно совместима. И на самих миграциях стоят lock_timeout = ''3s'' и statement_timeout, чтобы DDL не заблокировал прод на минуты.', 'Как откатить релиз, если миграция уже применилась? Почему CONCURRENTLY нельзя выполнять в транзакции?' from categories where slug = 'db-migrations';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как работают слои Docker и как вы собираете образ через multi-stage?', 'Каждая инструкция Dockerfile создаёт слой, слои кэшируются, поэтому COPY pom.xml до COPY src и RUN mvn dependency:go-offline дают кэш зависимостей: при изменении только кода Maven не качает всё заново. Количество слоёв влияет в основном на кэш и на размер: связанные команды объединяю через &&, а временные файлы удаляю в том же слое (rm -rf /var/lib/apt/lists/*), потому что удалённое в следующем слое всё равно остаётся в образе. Multi-stage: первый стейдж на maven:3.9-eclipse-temurin-21 компилирует и собирает jar, второй — на eclipse-temurin:21-jre или distroless, куда копируется только артефакт через COPY --from=builder /app/target/app.jar /app/app.jar; это убирает из финального образа компилятор, исходники и креды Maven и уменьшает образ примерно с 600 МБ до 200 МБ. Обязательные мелочи: .dockerignore с target и .git, USER non-root, ENTRYPOINT в exec-форме (java -jar app.jar), фиксированные теги образов вместо latest — иначе сборка невоспроизводима. HEALTHCHECK в образ не нужен, если в Kubernetes есть probes — они делают то же самое корректнее. На практике мы собирали jar в Jenkins на агентном docker-образе, а runtime-образ деплоили в кластер, и это дало предсказуемые размеры и меньше CVE, потому что в финальном образе нет тулчейна.', 'Как максимально эффективно кэшировать зависимости Maven в CI? Почему не стоит использовать тег latest?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Чем отличаются Pod, Deployment и Service, и как настраиваются probes и rolling update?', 'Pod — минимальная единица с одним или несколькими контейнерами (sidecar), Deployment управляет ReplicaSet-ами и обеспечивает rolling update, Service даёт стабильный ClusterIP и DNS с балансировкой только по готовым подам, Ingress отвечает за внешний доступ. Probes делю по смыслу: startupProbe даёт приложению время на старт (иначе на медленном старте liveness убьёт под раньше, чем JVM прогреется), readinessProbe определяет, отправлять ли трафик (если недоступна БД — под снимается с балансировки, но не перезапускается), livenessProbe перезапускает реально зависшее приложение. В Spring Boot развожу эндпоинты /actuator/health/liveness и /actuator/health/readiness, чтобы liveness не зависел от внешних зависимостей — иначе падение БД приведёт к циклическому перезапуску всех подов и превратит частичную деградацию в полный отказ. Rolling update настраиваю как maxSurge: 25%, maxUnavailable: 0 — при 4 репликах поды меняются по одному и ёмкость не проседает. Обязательно terminationGracePeriodSeconds и preStop hook (например, sleep 5 или отказ от новых запросов), чтобы in-flight запросы не терялись, потому что уход пода из эндпоинтов занимает время. Плюс PodDisruptionBudget, чтобы drain узла не убрал все реплики одновременно, и ресурсные requests — без них планировщик не сможет корректно разместить поды.', 'Почему liveness не должен проверять доступность БД? Что произойдёт, если readiness упадёт на всех подах сразу?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы настраиваете requests/limits, HPA и параметры JVM в контейнере?', 'requests определяют гарантированные ресурсы и используются планировщиком и HPA как база для процентов, limits — потолок: превышение memory limit даёт OOMKilled, превышение CPU limit даёт троттлинг по CFS, который для JVM особенно болезнен, потому что увеличивает паузы и хвостовые задержки. Поэтому CPU limit я стараюсь не ставить или ставить заметно выше requests, а memory request делаю равным limit, чтобы под был Guaranteed по памяти и не вытеснялся под нагрузкой. JVM в контейнере: с Java 11+ (у нас Java 21) она видит cgroup-лимиты, но heap по умолчанию — это 25% от лимита контейнера, поэтому при лимите 2Gi без настройки будет ~512 МБ heap и много нативной памяти сверху; правильно задавать -XX:MaxRAMPercentage=75 (и InitialRAMPercentage=75 для предсказуемости) вместо жёсткого -Xmx, тогда при изменении лимита heap пересчитается сам. Ещё нужны -XX:+UseG1GC (или Generational ZGC на Java 21 для малых пауз), -XX:MaxMetaspaceSize, -XX:MaxDirectMemorySize и -XX:+ExitOnOutOfMemoryError, иначе процесс может быть убит по OOM без явного исключения. HPA: масштабирование по CPU требует заданных requests, но при 5 RPS CPU не показателен, поэтому корректнее кастомная метрика (RPS, длина очереди, Kafka lag) через Prometheus Adapter; у нас HPA был скорее страховкой от аномалий. Обязательно minReplicas для доступности и behavior.scaleDown.stabilizationWindowSeconds ~300, чтобы не дёргать приложение. И отдельный расчёт: суммарное число соединений (реплики × размер пула Hikari) не должно превышать max_connections в PostgreSQL.', 'Сколько heap будет при лимите 2Gi и MaxRAMPercentage=75? Что делать, если приложение растёт по RSS при стабильном heap?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как диагностировать OOMKilled и CrashLoopBackOff и как правильно работать с ConfigMap и Secret?', 'OOMKilled видно в kubectl describe pod: Last State — Terminated, Reason — OOMKilled, Exit Code 137; дальше смотрю kubectl top pod, события (kubectl get events --sort-by=.lastTimestamp) и метрику container_memory_working_set_bytes в Grafana, потому что именно рабочий набор учитывается при убийстве процесса. Частая причина при живом heap — нативная память: metaspace, стеки потоков, direct buffers Netty, JIT-кэш, поэтому проверяю Native Memory Tracking (-XX:NativeMemoryTracking=summary + jcmd <pid> VM.native_memory summary) и держу MaxRAMPercentage с запасом 20–25%, а не 90%. CrashLoopBackOff — это не ошибка самого приложения, а нарастающий backoff после повторных падений; смотрю kubectl logs --previous и exit code: 1 — исключение на старте (обычно конфигурация или недоступная БД), 137 — убит по памяти, 143 — SIGTERM. Также полезны kubectl describe pod на события (FailedMount, ImagePullBackOff, Probe failed) и kubectl exec с проверкой переменных окружения. ConfigMap — для несекретной конфигурации (профиль application.yaml), Secret — для паролей и токенов; важно помнить, что Secret в Kubernetes по умолчанию только base64, а не шифрование, поэтому нужны шифрование etcd (EncryptionConfiguration) и строгий RBAC, а лучше хранение во внешнем Vault/Secret Manager. Обновление ConfigMap или Secret не перезапускает поды, если они прокинуты как env, поэтому деплой делаем через rollout restart или инструмент типа Reloader. И обязательное правило: не логировать то, что попало в Secret, и маскировать чувствительные поля в конфиге логирования.', 'Как отличить утечку heap от роста нативной памяти? Что делать, если под падает по startupProbe после замедления старта?' from categories where slug = 'docker-kubernetes';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Declarative или scripted pipeline, как вы работаете с агентами, секретами и параллельными стадиями?', 'Jenkinsfile у нас лежит в репозитории и проходит code review, то есть pipeline as code, а не настройка в UI. Declarative синтаксис (pipeline { agent { label ... } stages { ... } post { ... } }) читается проще, валидируется и покрывает 95% задач; scripted (node { }) нужен для сложной логики, а в declarative это делается через блок script внутри stage. Агенты: использую label, чтобы сборка шла на нужном пуле, либо agent { docker { image ''maven:3.9-eclipse-temurin-21'' } }, чтобы тулчейн жил в образе, а не дрейфовал на ноде. Параллельность — parallel стадии: юнит-тесты, интеграционные тесты и статический анализ идут одновременно, но с оглядкой на память агента, потому что Testcontainers в нескольких параллельных прогонах легко съедают ресурсы. Секреты только через withCredentials (usernamePassword, string, file) и привязки к переменным, никогда не echo; маскирование логов в Jenkins есть, но на него нельзя полагаться как на защиту. В post-блоке обязательно публикую junit-отчёт, JaCoCo и артефакты (archiveArtifacts), плюс ставлю timeout(time: 30, unit: ''MINUTES'') на весь пайплайн, чтобы зависший шаг не держал executor бесконечно. Для PR — отдельная облегчённая сборка без деплоя, деплой только с master/main и с ручным подтверждением для прода.', 'Как избежать конфликтов параллельных сборок на одном агенте? Где хранить секреты надёжнее, чем в Jenkins credentials?' from categories where slug = 'ci-cd';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы реализуете blue-green и canary деплой и как организован откат?', 'Blue-green: держим два окружения, активное и новое, после проверки переключаем Service или Ingress (селектор, вес в балансировщике) на новое и в случае проблемы мгновенно возвращаемся; минусы — двойное потребление ресурсов и необходимость совместимости схемы БД. Canary: выпускаем часть трафика на новую версию (у нас это делалось через nginx-ingress canary-аннотации или Istio VirtualService с весом по репликам, начинали с 10%), наблюдаем метрики ошибок и латентности 15–30 минут, затем повышаем вес до 100%. Обязательное условие обоих подходов — обратно совместимые миграции БД по схеме expand/contract, иначе canary-версия просто не сможет работать с текущей схемой, а откат приложения потребует отката БД. Откат в Kubernetes: kubectl rollout history deployment/app и kubectl rollout undo deployment/app --to-revision=N, но важно понимать, что он откатывает код, а не миграцию, поэтому мы заранее считали миграции совместимыми с предыдущей версией кода. В Jenkins это оформлено стадиями Deploy → Smoke → анализ (health-check, 5xx, латентность) → при провале автоматический Rollback-стейдж. Дополнительно в /actuator/info прокидываем версию и commit, чтобы по метрикам и логам видеть, какая именно версия генерирует ошибки, — без этого canary превращается в угадывание.', 'Как автоматически останавливать canary и по каким метрикам? Что делать с миграцией БД, если canary провалилась?' from categories where slug = 'ci-cd';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Что такое метрики RED и USE, какие типы метрик есть в Prometheus и как вы строите алерты?', 'RED — про сервисы: Rate (запросы в секунду), Errors (доля ошибок), Duration (латентность, обязательно по перцентилям p95/p99, а не средняя, потому что средняя скрывает хвосты). USE — про ресурсы: Utilization, Saturation, Errors (CPU, диск, пул соединений, heap JVM, длина очередей). В Prometheus четыре типа метрик: counter (монотонно растёт — http_server_requests_seconds_count, работаем через rate()/increase()), gauge (текущее значение — jvm_memory_used_bytes, hikaricp_connections_active), histogram (бакеты по времени — даёт histogram_quantile(0.95, sum(rate(http_server_requests_seconds_bucket[5m])) by (le))), и summary (квантили считает клиент, между инстансами не агрегируются, поэтому в микросервисах предпочитаю histogram). Алерты пишу по симптомам, а не по причинам: например, доля 5xx выше 1% за 5 минут или p95 выше 500 мс — это проблема пользователя, а CPU 80% сам по себе проблемой не является. Обязательно for: 5m, чтобы не поднимать дежурного на одиночном всплеске, и severity с разной маршрутизацией: warning в чат, critical — звонок. Отдельно алертю на отсутствие данных (up == 0 или пропавшие метрики), на насыщение (hikaricp_connections_pending > 0, длина очереди пула потоков, Kafka consumer lag) и на приближение к лимитам Kubernetes-контейнера. Каждый алерт должен ссылаться на дашборд и короткий runbook, иначе дежурный не знает, что делать, и начинается alert fatigue.', 'Чем histogram отличается от summary на практике? Как избавиться от alert fatigue, не потеряв критичные сигналы?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы собираете дашборды в Grafana, организуете логирование и корреляцию с трассировкой?', 'Дашборды строю по слоям: обзор сервиса (RED), JVM (heap, GC-паузы, потоки через Micrometer/actuator/prometheus или jmx_exporter), база данных (HikariCP, pg_stat), Kubernetes (поды, namespace), и обязательно делаю переменные по namespace/service/pod, чтобы один дашборд работал для всех окружений. Смысл дашборда — drill-down: с панели роста ошибок переходим в логи по traceId, а не начинаем расследование с нуля. Логирование — структурированный JSON (logstash-logback-encoder), в MDC кладу traceId и spanId, тогда в Loki/ELK по одному traceId видна вся цепочка между сервисами, включая Kafka. Корреляция требует единого набора полей (service, env, version, traceId) и дисциплины: INFO для бизнес-событий, WARN/ERROR для проблем, без PII и токенов в логах, без сообщений вроде start-processing без контекста. Трассировка — OpenTelemetry (spring-boot-starter или javaagent), экспорт через OTLP в Tempo/Jaeger, сэмплирование обычно 10% базово и 100% по ошибкам (tail-based), иначе хранение трасс становится дороже самих сервисов. Correlation id приходит от шлюза или клиента и пробрасывается в заголовки HTTP и Kafka-сообщений — без этого распределённую трассировку не собрать. На практике это давало инциденты, разбираемые за минуты: метрика показала рост ошибок, по traceId нашли конкретный внешний вызов, в логах увидели таймаут.', 'Как связать метрику с конкретным запросом? Что делать, если traceId не доезжает через Kafka?' from categories where slug = 'monitoring';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как выглядит тестовая пирамида в вашем проекте и как вы относитесь к покрытию более 80%?', 'Пирамида у нас такая: много быстрых юнит-тестов (JUnit 5, AssertJ, Mockito), меньше интеграционных (Spring Boot @SpringBootTest с Testcontainers, @DataJpaTest, WireMock для внешних HTTP) и совсем немного end-to-end, потому что сервис внутренний с нагрузкой до 5 RPS и держать большой слой UI-автотестов смысла нет. Покрытие более 80% у нас было качественным гейтом, но я всегда объясняю команде, что процент — это ограничитель, а не цель: важнее покрытие критических ветвей (расчёты, идемпотентность, обработка ошибок), чем формальные 100% в геттерах. Инструментально — JaCoCo с правилом jacoco:check (counter LINE, minimum 0.80) на reactor-сборке и отчёт в Jenkins/Sonar; полезнее общего процента quality gate на новом коде (new code coverage), потому что он не даёт постепенно снижать планку и не заставляет бегать за легаси. DTO, конфигурации и мапперы из подсчёта исключаю явными excludes, иначе метрика превращается в ритуал. Отдельно слежу, чтобы тест проверял поведение, а не реализацию: тесты, завязанные на внутренние вызовы, ломаются от любого рефакторинга и создают ложное чувство защиты. И тесты обязаны быть детерминированными: время через внедряемый Clock, никакой зависимости от порядка выполнения, случайность — с фиксированным seed.', 'Как измеряете покрытие именно нового кода? Что делать, если покрытие высокое, а продовые баги всё равно есть?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы используете Testcontainers и что тестируете интеграционно?', 'Testcontainers поднимает реальные зависимости в Docker прямо из теста: PostgreSQLContainer, MongoDBContainer, GenericContainer для Redis, Kafka через confluentinc/cp-kafka или Redpanda. Это принципиально надёжнее H2, потому что H2 не воспроизводит поведение PostgreSQL — типы, JSONB, MVCC, блокировки, ON CONFLICT, — и я видел ситуации, когда тесты на H2 зелёные, а на проде запрос падает. Настройка: @Testcontainers и @Container на static-полях, в Spring Boot 3.1+ — @ServiceConnection, который сам подставляет параметры подключения без @DynamicPropertySource. Контейнеры делаю per-class (static), а не per-method, включаю reuse (testcontainers.reuse.enable=true), чтобы не перезапускать Docker на каждый прогон, и на старте контейнера прогоняю Liquibase/Flyway — так тест проверяет ещё и миграции, что важно. Отдельный класс случаев — реальные транзакции и блокировки, там @Transactional-откат использовать нельзя, потому что он ломает сам сценарий, и данные чистятся явно (truncate или отдельные схемы). Для Kafka-тестов ждём события через Awaitility, а не Thread.sleep, иначе получаем flaky. В CI это работает на агентах с доступом к Docker; тяжёлые интеграционные наборы мы выносили в nightly, а в PR гоняли смоук-набор.', 'Чем @ServiceConnection лучше @DynamicPropertySource? Как чистить состояние между интеграционными тестами?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Mock или spy в Mockito и как вы боретесь с flaky tests?', 'Моки я использую для внешних зависимостей и проверки взаимодействий (verify), спаи — редко и аккуратно, потому что @Spy вызывает реальный код и делает тест хрупким: часть логики может уйти во внешние вызовы или медленные операции. Порядок предпочтения при проектировании теста: чистая логика без зависимостей → fake (in-memory реализация репозитория или клиента) → spy → mock; чем меньше моков, тем устойчивее тест к рефакторингу. Из практики: @ExtendWith(MockitoExtension.class), @Mock/@InjectMocks, when(...).thenReturn(...), ArgumentCaptor когда важно проверить полученный аргумент, verify(timeout) для асинхронных вызовов, и mockStatic только как крайняя мера — статические моки текут между тестами и плохо читаются. Flaky tests лечу по инженерному алгоритму: сначала карантин (исключение из гейта с тикетом), потом поиск причины — обычно это общий state между тестами, зависимость от порядка или времени, асинхронность без ожидания, занятый порт, внешний сервис, нестабильный контейнер. Правило: не «лечить» нестабильность повторами — rerunFailingTestsCount полезен только как диагностика, а не как решение. Также запрещено оставлять @Disabled без ссылки на задачу, иначе количество отключённых тестов растёт, и команда перестаёт верить красной сборке. Отдельно фиксирую время (Clock) и использую Awaitility там, где есть асинхронность.', 'Как протестировать метод, который зависит от текущего времени? Почему mockStatic считается опасным?' from categories where slug = 'testing';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы принимаете архитектурные решения и как защищаете их перед командой и стейкхолдерами?', 'Я начинаю не с решения, а с формулировки задачи и ограничений: какая нагрузка, какая команда, какие сроки, что нельзя менять, как быстро решение можно откатить. Дальше рассматриваю 2–3 варианта и сравниваю их по явным критериям: стоимость поддержки, сложность для команды, эксплуатационные риски, сроки, отзывчивость сообщества и наличие экспертизы внутри. Дальше разделяю решения на обратимые и необратимые: обратимые (выбор библиотеки, структура модуля) принимаю быстро сам, необратимые (модель данных, выбор БД, схема интеграции) обсуждаю с командой и, если риск высок, проверяю спайком или прототипом. Итог оформляю коротким ADR: контекст, варианты, решение, последствия — это сильно снижает споры спустя полгода, когда все уже забыли аргументы. Защищаю решение данными: результат нагрузочного теста, метрики, оценка сроков, а не «мне так кажется» — и признаю, если аргументы против сильнее моих. Если решение всё же принято не в мою пользу, я работаю на общий результат (disagree and commit), а не саботирую его. Пример из практики: выбор Liquibase вместо Flyway и отказ от Kafka для мелких уведомлений в пользу outbox-таблицы — оба решения защищали тем, что команда из 7 человек не должна поддерживать инфраструктуру, которую не тянет эксплуатировать.', 'Приведите пример решения, которое вы приняли, а потом изменили. Как вы действуете, если стейкхолдер требует другое?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Расскажите про конфликт в команде и как вы его разрешили.', 'Конфликты у меня в команде были в основном предметные, а не личные — например, спор про строгость код-ревью и про то, замораживать ли поставку ради крупного рефакторинга. Я стараюсь разводить человека и проблему: сначала разговор один на один, чтобы услышать аргументы, а не позицию в публичном чате. Дальше перевожу спор в критерии: что мы оптимизируем — сроки, качество, скорость онбординга, риск в проде, и прошу обе стороны сказать, что должно случиться, чтобы они поменяли мнение. Часто оказывается, что расхождение не в решении, а в разных оценках риска, и тогда спор решается данными: замером времени сборки, результатом спайка, статистикой по багам. Если консенсуса нет, решение принимаю я как ответственный, объясняю аргументы и фиксирую его в ADR или в тикете, чтобы не возвращаться к этому каждую неделю. Важно, чтобы после решения не осталось «проигравших»: я отдельно проговариваю с человеком, что его аргументы услышаны, и что при появлении этих признаков мы пересматриваем решение. Один такой спор про рефакторинг мы закрыли компромиссом: сделали рефакторинга ровно столько, сколько укладывалось в одну итерацию без переноса сроков, остальное вынесли в технический бэклог с приоритетом. Если бы конфликт стал устойчивым и токсичным, я бы подключал руководителя и HR — но до этого не доходило.', 'Что вы делаете, если конфликт между двумя разработчиками повторяется? Приведите пример, где вы потом поняли, что были неправы.' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как вы оцениваете задачи и сколько буфера закладываете?', 'Я оцениваю не «задачу», а весь путь до прода: разработка, тесты, ревью, миграции, выкатка, мониторинг и документация — если последние пункты не учитывать, оценка системно занижается. Сначала декомпозирую до задач размером 0.5–2 дня: то, что не удаётся разбить, почти всегда означает неясность требований, и это отдельный пункт для обсуждения. Дальше использую трёхточечную оценку (оптимистичная, реалистичная, пессимистичная) и в команде — planning poker, чтобы расхождение в оценках сразу вскрывало разные предположения. На неизвестность отдельно закладываю спайк с фиксированным таймбоксом: если за день не разобрались, эскалируем и меняем подход, а не тянем. Буфер зависит от неопределённости: для понятной задачи добавляю 20%, для задачи со сторонним сервисом или новой технологией — 50%, и это не «запас на лень», а компенсация рисков. Калибрую себя по фактам: смотрю velocity команды и cycle time в Jira, сравниваю оценки с фактическим временем и корректирую множитель; за 4,5 года у меня сложилось устойчивое представление, где я обычно ошибаюсь — чаще в недооценке интеграционной части и согласований, чем в коде. И я всегда говорю правду про срок, даже если она неприятная: перенос, названный заранее, стоит дешевле, чем аврал в конце.', 'Как вы оцениваете задачу, которую никто в команде раньше не делал? Как поступаете, если оценка не устраивает руководство?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Расскажите про менторинг: как вы растили разработчиков, у вас же команда 7 человек?', 'Я был главным разработчиком и фактически отвечал за рост пяти разработчиков разных уровней, включая джунов, которых мы брали в команду. Начинал с онбординга: неделя на окружение и чтение кода, понятная первая задача с парным программированием, чтобы человек не сидел один с незнакомым стеком. Дальше системно работал через код-ревью: не переписывал код сам, а объяснял, почему так, и оставлял ссылки на документацию и на наши ADR — ревью должно учить, а не просто закрывать PR. Раз в неделю делал короткие 1:1, где обсуждали не только задачи, но и что человек хочет изучить, куда расти; на этой основе составлял план на квартал (например, взять на себя модуль, провести миграцию, выступить с демо). Практика важнее лекций, поэтому я отдавал джунам всё более ответственные куски и сознательно не подстраховывал их каждую минуту, но держал рядом на случай инцидента. Результат в моей честной формулировке: через пару месяцев человек обычно начинал делать самостоятельные PR, а часть ребят брала полную ответственность за отдельный сервис; конкретных цифр вроде «сократили баги на 40%» я не привожу, потому что мы их не измеряли корректно. Отдельно я учил не код-стилю, а инженерному мышлению: как формулировать вопрос, как читать план EXPLAIN, как проверить гипотезу логом, как писать постмортем без поиска виноватого. И у себя тоже брал обратную связь на 1:1: несколько процессов (например, длинные ежедневные стендапы) мы поменяли именно по замечаниям команды.', 'Приведите конкретный пример разработчика, которого вы вырастили: что было в начале, что в конце. Что делать с тем, кто не растёт?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Расскажите про вашу ошибку или провал и какие выводы вы сделали.', 'Моя самая полезная ошибка — недооценка миграции БД: я выкатил изменение схемы в тот момент, когда оно было совместимо с новым кодом, но не с предыдущей версией, и при откате приложения старая версия уже не работала, что затянуло восстановление и добавило ручной работы. Формально виноват был я как автор миграции и главный разработчик, а не «стечение обстоятельств»: я не проговорил сценарий отката до начала работ. Что я сделал после: мы разобрали ситуацию постмортемом без поиска виноватого, зафиксировали, что миграция всегда должна быть совместима с предыдущей версией кода, и добавили чек-лист в процесс (expand/contract, lock_timeout, прогон на копии прода, обязательная проверка сценария откатa). Второй вывод был про наблюдение: у нас не было сигнала, который бы показал проблему раньше, поэтому добавили алерт на рост ошибок БД и метрику по латентности запросов. Третий — про коммуникацию: я слишком поздно сообщил о проблеме, когда пытался разобраться сам; теперь правило простое — флаг о проблеме поднимается в первые минуты, а не когда она уже у всех. Из этой истории я сделал привычку спрашивать себя до деплоя «что будет, если мы откатимся через 10 минут», и с тех пор мы ни разу не застряли на откате. Ещё я стал честнее с оценками: то, что казалось «тривиальной миграцией», я теперь оцениваю с учётом времени на подготовку и проверку.', 'Что бы вы сейчас сделали иначе в той ситуации? Как вы сообщаете о своей ошибке руководству?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Почему вы уходите из Альфа-Банка?', 'Я не убегаю от проблем: в Альфа-Банке я получил очень полезный опыт — Java 21 и Kotlin, PostgreSQL, Kafka, Kubernetes, миграции, микросервисы, ответственность за архитектурные решения и менторинг, и ухожу я по-хорошему. Причина в том, что в текущей роли я упёрся в потолок роста: количество и сложность задач растут не так быстро, как я хочу, а масштаб систем не даёт мне нового инженерного опыта. Хочу работать в команде, где я смогу больше отвечать за архитектуру в целом, а не за отдельные сервисы, и где есть более сильные инженеры, у которых можно учиться — это для меня главный мотив. Второй фактор — международный контекст: хочу больше задач и коммуникации на английском, потому что язык у меня B1 и практика ему нужна как воздух, а в текущих условиях такой среды мало. Третий момент — масштаб нагрузки: у нас внутренняя система с 5 RPS, и я хочу поработать там, где на порядки больше трафика и данные измеряются миллиардами строк, чтобы проверить и усилить свои решения. Про деньги я говорю честно как про один из факторов, но не как про основной, иначе это было бы неправдой. Уйти я готов аккуратно: доведу передачу знаний, оформлю документацию и не буду говорить плохо о компании, потому что мне действительно есть за что её благодарить.', 'Что для вас важнее в новом месте — задачи, деньги или команда? Что должно случиться, чтобы вы ушли из новой компании через год?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как отвечать на вопрос про нагрузку 5 RPS — почему это нормально для внутренних систем и что вы вообще делали на такой нагрузке?', 'Я отвечаю спокойно и без оправданий: 5 RPS в среднем — это профиль конкретной внутренней системы, и низкая средняя нагрузка не означает, что проектировать там нечего. Во-первых, важна не средняя, а характер: тяжёлые batch-операции, отчёты, пересчёты и запуск по расписанию — они могут давать длительные CPU-нагрузки и блокировки при скромном RPS. Во-вторых, критичность: внутренняя банковская система обрабатывает данные, где ошибка стоит денег и репутации, поэтому требования к корректности, идемпотентности, транзакциям и надёжности выше, чем к пропускной способности. В-третьих, что я делал на этих объёмах: проектировал модель данных на таблицах ~1 млн строк, разбирал планы EXPLAIN, делал zero-downtime миграции, настраивал пул соединений HikariCP и деплой в Kubernetes с probes и лимитами — это и есть работа с данными, просто в другом масштабе. Плюс я честно говорю, что понимаю разницу: при 5 RPS я не решал задачи шардирования, кэширования под миллионы попаданий и борьбы за единицы миллисекунд, и мне этот опыт интересен и нужен. Чтобы говорить о запасе, а не угадывать, мы делали нагрузочные проверки (Gatling/k6) и понимали, сколько система держит сверх текущего профиля. Если интервьюер ждёт миллионы RPS, я не буду врать: скажу, что такого опыта нет, но объясню, как я думаю про масштабирование — узкие места, реплики только для чтения, партиционирование, кэш, асинхронность.', 'Какие узкие места появятся у вашей системы при росте нагрузки в 100 раз? Что вы сделали бы первым делом?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'Как объяснить 11 лет в рознице: не помешает ли этот опыт и почему вы вообще перешли в разработку?', 'Я объясняю это прямо и без неловкости: 11 лет в рознице руководителем — осознанный отрезок карьеры, а не пробел, и он дал навыки, которые в разработке работают напрямую. Это управление людьми и процессами, планирование при жёстких сроках, работа с деньгами и P&L-логикой, разговоры с требовательными клиентами, ответственность за результат без права «не справился». В разработку я перешёл сознательно: сначала учился сам, писал код, потом получил первую разработческую роль, и именно этот путь дал мне управленческую часть роли главного разработчика быстрее, чем у коллег-инженеров без такого бэкграунда. При этом я не преподношу это как замену техническому опыту: у меня 4,5 года Java-разработки, и я честно говорю, что этот стаж короче, чем у кандидатов, которые пишут код 10 лет. Обратная сторона — я осознанно догонял и догоняю: стек Java 21, Kotlin, PostgreSQL, Kafka, Docker, Kubernetes, Jenkins, чтение спецификаций на английском. Если спросят про возраст и уровень, отвечу, что переход был осознанным, и моя ценность — в сочетании инженерной практики и умения отвечать за команду и результат. Розничный опыт помогает мне и в интервью, и в работе: я умею считать деньги бизнеса и говорить с заказчиком на его языке.', 'Почему вы не вернулись в управление, а пошли в разработку? Что для вас важнее — руководить или писать код?' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'У вас B1 по английскому — как компенсируете скромную разговорную практику?', 'Я не завышаю уровень: у меня B1, читаю техническую документацию, статьи и RFC, веду переписку, пишу коммиты и описания PR на английском, а вот спонтанная устная речь даётся тяжелее. Компенсирую системно: ежедневно минимум 30–60 минут английского — чтение документации по стеку, короткие письменные заметки по-английски, а по разговорной части занимаюсь с преподавателем и разыгрываю технические сценарии (объяснение архитектуры, разбор инцидента, защита решения). Отдельно готовлю словарь под свою работу: терминология по инцидентам, релизам, миграциям, архитектурным решениям — так речь становится конкретной и не рассыпается на общие фразы. В интервью предлагаю честный вариант: если нужно, часть разговора проведу на английском, и предпочту, чтобы лучше оценили смысл, чем акцент. Дальний план — выйти на уверенный B2 в горизонте 6–12 месяцев, с конкретной целью: свободно вести планёрки, демо и разборы инцидентов и писать технические документы без переводчика. Ещё один практический приём — не бояться говорить с ошибками: хуже не сказать ничего, чем сказать с грамматической ошибкой, и я это регулярно себе напоминаю. В команде с международным составом я готов к старту на английском с первого дня, просто первые недели буду более медленным в разговоре.', 'Что будете делать, если на встрече не поняли вопрос на английском? Опишите ваш последний проект на английском в двух минутах.' from categories where slug = 'behavioral';
insert into questions (category_id, difficulty, body, answer, followup) select id, 'MIDDLE', 'В вашем резюме периоды опыта пересекаются — что это и как вы это объясняете?', 'Я отвечаю на это прямо и готовлю ответ заранее, потому что расхождение, найденное рекрутером самостоятельно, выглядит хуже любого честного объяснения. Пересечения бывают по трём причинам: реальное совмещение (консалтинг, менторство, проектная работа помимо основного места), переход между компаниями, когда я продолжал добивать задачи по прошлому проекту, и банальная ошибка в месяцах при вёрстке резюме. Первые два я указываю явно: помечаю запись как совместительство или проектную занятость и в комментарии пишу, сколько часов это занимало и на что влияло — главное, чтобы не выглядело как попытка «нарастить» стаж. Если это ошибка в датах, её надо просто исправить, а не защищать: я сверяю даты с трудовой книжкой и договорами. Отдельно учитываю, что банки и крупные компании делают проверку кандидата (СБ, служба безопасности, background check), поэтому там важна точность до месяца, и любые параллельные активности лучше показать заранее, чем получить вопрос от проверяющего. Ещё правило — не раскрывать детали под NDA: могу сказать, что работал по такому-то профилю, без названий систем и данных. Итого моя стратегия: точные даты, явная пометка совмещений, готовность подтвердить документами, никаких попыток скрыть.', 'Что делать, если работодатель запрещал совместительство? Как вы отреагируете на вопрос службы безопасности о параллельной работе?' from categories where slug = 'behavioral';
